var __index = {"config":{"lang":["en"],"separator":"[\\s\\u200b\\-]","pipeline":["stemmer"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"Home","text":""},{"location":"index.html#\u4e3b\u9875","title":"\u4e3b\u9875","text":""},{"location":"linux/linux-system-programming/file_io.html","title":"\u6587\u4ef6\u200b I/O","text":""},{"location":"linux/linux-system-programming/file_io.html#\u6587\u4ef6-IO","title":"\u6587\u4ef6\u200b I/O","text":""},{"location":"linux/linux-system-programming/file_io.html#\u6587\u4ef6\u63cf\u8ff0\u7b26","title":"\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26","text":"<p>\u200b\u5728\u200b Unix/Linux \u200b\u64cd\u4f5c\u7cfb\u7edf\u200b\u4e2d\u200b\uff0c\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\uff08File Descriptor\uff0c\u200b\u7b80\u79f0\u200b fd\uff09\u200b\u662f\u200b\u5185\u6838\u200b\u4e3a\u4e86\u200b\u9ad8\u6548\u200b\u7ba1\u7406\u200b\u5df2\u200b\u88ab\u200b\u6253\u5f00\u200b\u7684\u200b I/O \u200b\u8d44\u6e90\u200b\u800c\u200b\u63d0\u4f9b\u200b\u7684\u200b\u4e00\u4e2a\u200b\u62bd\u8c61\u200b\u6307\u793a\u200b\u7b26\u200b\u3002\u200b\u5b83\u200b\u672c\u8d28\u200b\u662f\u200b\u4e00\u4e2a\u200b\u975e\u8d1f\u200b\u6574\u6570\u200b\uff0c\u200b\u5f53\u200b\u8fdb\u7a0b\u200b\u901a\u8fc7\u200b\u7cfb\u7edf\u200b\u8c03\u7528\u200b\u6253\u5f00\u200b\u4e00\u4e2a\u200b\u73b0\u6709\u200b\u6587\u4ef6\u200b\u6216\u200b\u521b\u5efa\u200b\u4e00\u4e2a\u200b\u65b0\u200b\u6587\u4ef6\u200b\u65f6\u200b\uff0c\u200b\u5185\u6838\u200b\u4f1a\u200b\u5411\u200b\u8be5\u200b\u8fdb\u7a0b\u200b\u8fd4\u56de\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\uff0c\u200b\u4f5c\u4e3a\u200b\u540e\u7eed\u200b\u6240\u6709\u200b I/O \u200b\u64cd\u4f5c\u200b\uff08\u200b\u5982\u200b <code>read</code>\u3001<code>write</code>\uff09\u200b\u7684\u200b\u201c\u200b\u51ed\u8bc1\u200b\u201d\u3002</p> <p>\u200b\u79c9\u627f\u200b Unix/Linux \u201c\u200b\u4e00\u5207\u200b\u7686\u200b\u6587\u4ef6\u200b\u201d \u200b\u7684\u200b\u6838\u5fc3\u200b\u54f2\u5b66\u200b\uff0c\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u4e0d\u4ec5\u200b\u53ef\u4ee5\u200b\u6307\u5411\u200b\u666e\u901a\u200b\u6587\u4ef6\u200b\u548c\u200b\u76ee\u5f55\u200b\uff0c\u200b\u8fd8\u200b\u80fd\u200b\u7edf\u4e00\u200b\u8868\u793a\u200b\u6240\u6709\u200b\u7c7b\u578b\u200b\u7684\u200b\u5df2\u200b\u6253\u5f00\u200b\u8d44\u6e90\u200b\uff0c\u200b\u5305\u62ec\u200b\u7ba1\u9053\u200b\uff08Pipe\uff09\u3001\u200b\u547d\u540d\u200b\u7ba1\u9053\u200b\uff08FIFO\uff09\u3001\u200b\u7f51\u7edc\u200b\u5957\u200b\u63a5\u5b57\u200b\uff08Socket\uff09\u3001\u200b\u7ec8\u7aef\u8bbe\u5907\u200b\u4ee5\u53ca\u200b\u5176\u4ed6\u200b\u8bbe\u5907\u200b\u6587\u4ef6\u200b\u3002</p> <p>\u200b\u5728\u200b\u5e95\u5c42\u200b\u5b9e\u73b0\u200b\u4e0a\u200b\uff0c\u200b\u64cd\u4f5c\u7cfb\u7edf\u200b\u7684\u200b\u8fdb\u7a0b\u200b\u63a7\u5236\u200b\u5757\u200b\uff08PCB\uff09\u200b\u4e2d\u200b\u7ef4\u62a4\u200b\u4e00\u5f20\u200b \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u8868\u200b\u3002\u200b\u8fd9\u200b\u610f\u5473\u7740\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u200b\u662f\u200b \u200b\u8fdb\u7a0b\u200b\u79c1\u6709\u200b \u200b\u7684\u200b\uff0c\u200b\u4e0d\u540c\u200b\u8fdb\u7a0b\u200b\u5404\u81ea\u200b\u72ec\u7acb\u200b\u7ba1\u7406\u200b\u3002\u200b\u5f53\u200b\u8fdb\u7a0b\u200b\u8bf7\u6c42\u200b\u5206\u914d\u200b\u65b0\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u65f6\u200b\uff0c\u200b\u5185\u6838\u200b\u9075\u5faa\u200b\u201c\u200b\u6700\u4f4e\u200b\u53ef\u7528\u200b\u539f\u5219\u200b\u201d\uff0c\u200b\u5373\u200b \u200b\u603b\u662f\u200b\u8fd4\u56de\u200b\u5f53\u524d\u200b\u8fdb\u7a0b\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u8868\u4e2d\u200b\u672a\u200b\u88ab\u200b\u4f7f\u7528\u200b\u7684\u200b\u6700\u5c0f\u200b\u975e\u8d1f\u200b\u6574\u6570\u200b\u3002\u200b\u503c\u5f97\u6ce8\u610f\u200b\u7684\u200b\u662f\u200b\uff0c\u200b\u6bcf\u4e2a\u200b\u8fdb\u7a0b\u200b\u5728\u200b\u542f\u52a8\u65f6\u200b\uff0c\u200b\u7cfb\u7edf\u200b\u4f1a\u200b\u9ed8\u8ba4\u200b\u6253\u5f00\u200b\u4e09\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\uff1a0\uff08\u200b\u6807\u51c6\u200b\u8f93\u5165\u200b\uff09\u30011\uff08\u200b\u6807\u51c6\u200b\u8f93\u51fa\u200b\uff09 \u200b\u548c\u200b 2\uff08\u200b\u6807\u51c6\u200b\u9519\u8bef\u200b\uff09\uff0c\u200b\u5728\u200b\u4f7f\u7528\u200b\u7684\u200b\u65f6\u5019\u200b\u6700\u597d\u200b\u4f7f\u7528\u200b\u5b83\u4eec\u200b\u7684\u200b\u7b26\u53f7\u200b\u5e38\u91cf\u200b\uff1a<code>STDIN_FILENO</code>\u3001<code>STDOUT_FILENO</code> \u200b\u4ee5\u53ca\u200b <code>STDERR_FILENO</code>\u3002\u200b\u56e0\u6b64\u200b\u7a0b\u5e8f\u200b\u4e3b\u52a8\u200b\u6253\u5f00\u200b\u7684\u200b\u7b2c\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u901a\u5e38\u200b\u4f1a\u200b\u5206\u914d\u200b\u5230\u200b\u63cf\u8ff0\u7b26\u200b 3\u3002</p> <p></p>"},{"location":"linux/linux-system-programming/file_io.html#\u5e38\u7528\u51fd\u6570","title":"\u5e38\u7528\u200b\u51fd\u6570","text":"<p>\u200b\u5728\u200b Unix/Linux \u200b\u7cfb\u7edf\u200b\u7f16\u7a0b\u200b\u4e2d\u200b\uff0c\u200b\u5e38\u7528\u200b\u7684\u200b\u6587\u4ef6\u200b I/O \u200b\u51fd\u6570\u200b\u53ea\u200b\u9700\u8981\u200b\u8fd9\u4e2a\u200b\u4e94\u4e2a\u200b\uff1a<code>open</code>\u3001<code>close</code>\u3001<code>read</code>\u3001<code>write</code> \u200b\u4ee5\u53ca\u200b <code>lseek</code>\u3002\u200b\u8fd9\u4e9b\u200b\u51fd\u6570\u200b\u90fd\u200b\u662f\u200b\u4e0d\u5e26\u200b\u7f13\u51b2\u200b\u7684\u200b I/O\uff0c\u200b\u6bcf\u6b21\u200b\u8c03\u7528\u200b\u90fd\u200b\u4f1a\u200b\u76f4\u63a5\u200b\u89e6\u53d1\u200b\u7cfb\u7edf\u200b\u8c03\u7528\u200b\uff0c\u200b\u4ece\u200b\u7528\u6237\u200b\u5c42\u6001\u200b\u5207\u6362\u200b\u81f3\u200b\u5185\u6838\u200b\u6001\u200b\uff0c\u200b\u7531\u200b\u5185\u6838\u200b\u6765\u200b\u5904\u7406\u200b\u6570\u636e\u200b\u3002</p>"},{"location":"linux/linux-system-programming/file_io.html#\u6253\u5f00--\u5173\u95ed","title":"\u6253\u5f00\u200b &amp; \u200b\u5173\u95ed","text":"<pre><code>#include &lt;sys/types.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;fcntl.h&gt;\n\n/**\n * @brief \u200b\u6253\u5f00\u200b pathname \u200b\u6240\u200b\u6807\u8bc6\u200b\u7684\u200b\u6587\u4ef6\u200b\n * @param pathname  \u200b\u6587\u4ef6\u200b\u8def\u5f84\u540d\u200b\n * @param flags     \u200b\u6587\u4ef6\u200b\u7684\u200b\u6253\u5f00\u65b9\u5f0f\u200b\n * @param mode      \u200b\u65b0\u521b\u5efa\u200b\u6587\u4ef6\u200b\u7684\u200b\u6587\u4ef6\u200b\u6743\u9650\u200b\n * @return \u200b\u6210\u529f\u200b\u8fd4\u56de\u200b\u53ef\u7528\u200b\u8303\u56f4\u200b\u5185\u200b\u6700\u5c0f\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\uff0c\u200b\u5931\u8d25\u200b\u8fd4\u56de\u200b -1\uff0cerrno \u200b\u6807\u8bc6\u200b\u9519\u8bef\u200b\u539f\u56e0\u200b\n *\n */\nint open(const char *pathname, int flags);\nint open(const char *pathname, int flags, mode_t mode);\n\n#include &lt;unistd.h&gt;\n\n/**\n * @brief \u200b\u5173\u95ed\u200b\u5df2\u200b\u5df2\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param fd \u200b\u5df2\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @return \u200b\u6210\u529f\u200b\u5173\u95ed\u200b\u8fd4\u56de\u200b 0\uff0c\u200b\u5173\u95ed\u200b\u5931\u8d25\u200b\u8fd4\u56de\u200b -1\uff0cerrno \u200b\u6807\u8bc6\u200b\u9519\u8bef\u200b\u539f\u56e0\u200b\n *\n */\nint close(int fd);\n</code></pre> <p>C \u200b\u8bed\u8a00\u200b\u7684\u200b\u5c0f\u200b\u7ec6\u8282\u200b\uff1a\u200b\u4e3a\u4ec0\u4e48\u200b\u4f1a\u200b\u6709\u200b\u4e24\u4e2a\u200b <code>open</code> \u200b\u51fd\u6570\u200b\uff1f</p> <p>\u200b\u901a\u8fc7\u200b man \u200b\u624b\u518c\u200b\u67e5\u770b\u200b <code>open</code> \u200b\u63a5\u53e3\u200b\u4f1a\u200b\u53d1\u73b0\u200b\u6709\u200b\u4e24\u4e2a\u200b\u5b9e\u73b0\u200b\u51fd\u6570\u200b\uff0c\u200b\u4f46\u662f\u200b C \u200b\u8bed\u8a00\u200b\u672c\u8eab\u200b\u662f\u200b\u4e0d\u200b\u652f\u6301\u200b\u51fd\u6570\u200b\u91cd\u8f7d\u200b\u3002\u200b\u5b9e\u9645\u4e0a\u200b\u5728\u200b Linux \u200b\u7684\u200b C \u200b\u5e93\u4e2d\u200b\uff0c<code>open</code> \u200b\u662f\u200b\u901a\u8fc7\u200b\u53d8\u53c2\u200b\u51fd\u6570\u200b\u5b9e\u73b0\u200b\u7684\u200b\uff0c\u200b\u5176\u200b\u771f\u5b9e\u200b\u539f\u578b\u200b\u7c7b\u4f3c\u200b <code>int open(const char *pathname, int flags, ...);</code>\u3002\u200b\u5f53\u200b\u4f60\u200b\u7684\u200b <code>flags</code> \u200b\u4e2d\u200b\u5305\u542b\u200b\u4e86\u200b <code>O_CREAT</code>\uff08\u200b\u5373\u200b\u9700\u8981\u200b\u521b\u5efa\u200b\u65b0\u200b\u6587\u4ef6\u200b\uff09\u200b\u65f6\u200b\uff0c\u200b\u4f60\u200b\u5fc5\u987b\u200b\u4f20\u5165\u200b\u7b2c\u4e09\u4e2a\u200b\u53c2\u6570\u200b <code>mode</code>\uff0c\u200b\u5426\u5219\u200b\u521b\u5efa\u200b\u51fa\u200b\u7684\u200b\u6587\u4ef6\u200b\u6743\u9650\u200b\u5c06\u200b\u662f\u200b\u968f\u673a\u200b\u7684\u200b\u4e71\u7801\u200b\u6743\u9650\u200b\u3002</p>"},{"location":"linux/linux-system-programming/file_io.html#flag-\u53c2\u6570","title":"<code>flag</code> \u200b\u53c2\u6570","text":"<p><code>flags</code> \u200b\u53c2\u6570\u200b\u5fc5\u987b\u200b\u5305\u542b\u200b\u4e09\u4e2a\u200b\u8bbf\u95ee\u200b\u6a21\u5f0f\u200b\u4e4b\u4e00\u200b\uff1a<code>O_RDONLY</code>\u3001<code>O_WRONLY</code> \u200b\u6216\u200b <code>O_RDWR</code>\uff0c\u200b\u5206\u522b\u200b\u8868\u793a\u200b\u4ee5\u200b\u53ea\u8bfb\u200b\u3001\u200b\u53ea\u200b\u5199\u200b\u6216\u200b\u8bfb\u5199\u200b\u6a21\u5f0f\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u3002\u200b\u9664\u6b64\u4e4b\u5916\u200b\uff0c<code>flags</code> \u200b\u53ef\u4ee5\u200b\u5305\u542b\u200b\u96f6\u4e2a\u200b\u6216\u200b\u591a\u4e2a\u200b\u6587\u4ef6\u521b\u5efa\u200b\u6807\u5fd7\u200b\u548c\u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\uff0c\u200b\u5e76\u200b\u8fdb\u884c\u200b\u6309\u200b \u200b\u4f4d\u6216\u200b(<code>|</code>) \u200b\u8fd0\u7b97\u200b\u3002</p> \u200b\u6807\u5fd7\u200b \u200b\u7528\u9014\u200b <code>O_APPEND</code> \u200b\u603b\u662f\u200b\u6587\u4ef6\u200b\u5c3e\u90e8\u200b\u8ffd\u52a0\u200b\u6570\u636e\u200b <code>O_ASYNC</code> \u200b\u5f53\u200b I/O \u200b\u64cd\u4f5c\u200b\u53ef\u884c\u200b\u65f6\u200b\uff0c\u200b\u4ea7\u751f\u200b\u4fe1\u53f7\u200b\uff08signal\uff09\u200b\u901a\u77e5\u200b\u8fdb\u7a0b\u200b <code>O_CLOEXEC</code> \u200b\u4e3a\u200b\u65b0\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u542f\u7528\u200b close-on-exec \u200b\u6807\u5fd7\u200b <code>O_CREAT</code> \u200b\u82e5\u200b\u6587\u4ef6\u200b\u4e0d\u200b\u5b58\u5728\u200b\u5219\u200b\u521b\u5efa\u200b\u5b83\u200b\uff0c\u200b\u4f7f\u7528\u200b\u6b64\u9879\u200b\uff0c<code>open</code> \u200b\u51fd\u6570\u200b\u9700\u200b\u540c\u65f6\u200b\u8bf4\u660e\u200b\u7b2c\u200b 3 \u200b\u4e2a\u200b\u53c2\u6570\u200b <code>mode</code>\uff0c\u200b\u7528\u200b <code>mode</code> \u200b\u6307\u5b9a\u200b\u8be5\u200b\u65b0\u200b\u6587\u4ef6\u200b\u7684\u200b\u8bbf\u95ee\u200b\u6743\u9650\u200b <code>O_DIRECTORY</code> \u200b\u5982\u679c\u200b <code>pathname</code> \u200b\u5f15\u7528\u200b\u7684\u200b\u4e0d\u662f\u200b\u76ee\u5f55\u200b\uff0c\u200b\u5219\u200b\u51fa\u9519\u200b <code>O_EXCL</code> \u200b\u5982\u679c\u200b\u540c\u65f6\u200b\u6307\u5b9a\u200b\u4e86\u200b <code>O_CREAT</code>\uff0c\u200b\u800c\u200b\u6587\u4ef6\u200b\u5df2\u7ecf\u200b\u5b58\u5728\u200b\uff0c\u200b\u5219\u200b\u51fa\u9519\u200b\u3002\u200b\u7528\u6b64\u200b\u53ef\u4ee5\u200b\u6d4b\u8bd5\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u662f\u5426\u200b\u5b58\u5728\u200b\uff0c\u200b\u5982\u679c\u200b\u4e0d\u200b\u5b58\u5728\u200b\uff0c\u200b\u5219\u200b\u521b\u5efa\u200b\u6b64\u200b\u6587\u4ef6\u200b\uff0c\u200b\u8fd9\u4f7f\u200b\u6d4b\u8bd5\u200b\u548c\u200b\u521b\u5efa\u200b\u4e24\u8005\u200b\u6210\u4e3a\u200b\u4e00\u4e2a\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b <code>O_LARGFILE</code> \u200b\u5728\u200b 32 \u200b\u4f4d\u200b\u7cfb\u7edf\u200b\u4e2d\u200b\u4f7f\u7528\u200b\u6b64\u200b\u6807\u5fd7\u200b\u6253\u5f00\u200b\u5927\u200b\u6587\u4ef6\u200b <code>O_NOATIME</code> \u200b\u8c03\u7528\u200b <code>read</code> \u200b\u65f6\u200b\uff0c\u200b\u4e0d\u200b\u4fee\u6539\u200b\u6587\u4ef6\u200b\u6700\u8fd1\u200b\u8bbf\u95ee\u200b\u65f6\u95f4\u200b <code>O_NOCTTY</code> \u200b\u5982\u679c\u200b <code>pathname</code> \u200b\u5f15\u7528\u200b\u7684\u200b\u662f\u200b\u7ec8\u7aef\u8bbe\u5907\u200b\uff0c\u200b\u5219\u200b\u4e0d\u200b\u5c06\u200b\u8be5\u200b\u8bbe\u5907\u200b\u5206\u914d\u200b\u4f5c\u4e3a\u200b\u6b64\u200b\u8fdb\u7a0b\u200b\u7684\u200b\u63a7\u5236\u200b\u7ec8\u7aef\u200b <code>O_NOFOLLOW</code> \u200b\u5982\u679c\u200b <code>pathname</code> \u200b\u5f15\u7528\u200b\u7684\u200b\u662f\u200b\u4e00\u4e2a\u200b\u7b26\u53f7\u200b\u94fe\u63a5\u200b\uff0c\u200b\u5219\u200b\u51fa\u9519\u200b <code>O_NONBLOCK</code> \u200b\u4ee5\u975e\u200b\u963b\u585e\u200b\u65b9\u5f0f\u200b\u6253\u5f00\u200b <code>O_SYNC</code> \u200b\u4f7f\u200b\u6bcf\u6b21\u200b <code>write</code> \u200b\u7b49\u5f85\u200b\u7269\u7406\u200b I/O \u200b\u64cd\u4f5c\u200b\u5b8c\u6210\u200b\uff0c\u200b\u5305\u62ec\u200b\u7531\u8be5\u200b <code>write</code> \u200b\u64cd\u4f5c\u200b\u5f15\u8d77\u200b\u7684\u200b\u6587\u4ef6\u5c5e\u6027\u200b\u66f4\u65b0\u200b\u6240\u200b\u9700\u200b\u7684\u200b I/O <code>O_TRUNC</code> \u200b\u5982\u679c\u200b\u6b64\u200b\u6587\u4ef6\u200b\u5b58\u5728\u200b\uff0c\u200b\u800c\u4e14\u200b\u4e3a\u200b\u53ea\u200b\u5199\u200b\u6216\u200b\u8bfb\u5199\u200b\u6210\u529f\u200b\u6253\u5f00\u200b\uff0c\u200b\u5219\u200b\u5c06\u200b\u5176\u200b\u957f\u5ea6\u200b\u622a\u65ad\u200b\u4e3a\u200b 0 <code>O_TTY_INIT</code> \u200b\u5982\u679c\u200b\u6253\u5f00\u200b\u8fd8\u200b\u672a\u200b\u6253\u5f00\u200b\u7684\u200b\u7ec8\u7aef\u8bbe\u5907\u200b\uff0c\u200b\u8bbe\u7f6e\u200b\u975e\u6807\u51c6\u200b <code>termios</code> \u200b\u53c2\u6570\u503c\u200b\uff0c\u200b\u4f7f\u200b\u5176\u200b\u7b26\u5408\u200b Single UNIX Specification <code>O_DSYNC</code> \u200b\u4f7f\u200b\u6bcf\u6b21\u200b <code>write</code> \u200b\u8981\u200b\u7b49\u5f85\u200b\u7269\u7406\u200b I/O \u200b\u64cd\u4f5c\u200b\u5b8c\u6210\u200b\uff0c\u200b\u4f46\u662f\u200b\u5982\u679c\u200b\u8be5\u200b\u5199\u200b\u64cd\u4f5c\u200b\u5e76\u200b\u4e0d\u200b\u5f71\u54cd\u200b\u8bfb\u53d6\u200b\u521a\u200b\u5199\u5165\u200b\u7684\u200b\u6570\u636e\u200b\uff0c\u200b\u5219\u200b\u4e0d\u200b\u9700\u200b\u7b49\u5f85\u200b\u6587\u4ef6\u5c5e\u6027\u200b\u88ab\u200b\u66f4\u65b0\u200b <code>O_RSYNC</code> \u200b\u4f7f\u200b\u6bcf\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u4f5c\u4e3a\u200b\u53c2\u6570\u200b\u8fdb\u884c\u200b\u7684\u200b <code>read</code> \u200b\u64cd\u4f5c\u200b\u7b49\u5f85\u200b\uff0c\u200b\u76f4\u5230\u200b\u6240\u6709\u200b\u5bf9\u200b\u6587\u4ef6\u200b\u540c\u200b\u4e00\u90e8\u5206\u200b\u6302\u200b\u8d77\u200b\u7684\u200b\u5199\u200b\u64cd\u4f5c\u200b\u90fd\u200b\u5b8c\u6210\u200b <p>\u200b\u5728\u200b\u65e9\u671f\u200b\u7684\u200b UNIX \u200b\u7cfb\u7edf\u200b\u7248\u672c\u200b\u4e2d\u200b\uff0c\u200b\u65e0\u6cd5\u200b\u6253\u5f00\u200b\u4e00\u4e2a\u200b\u5c1a\u672a\u200b\u5b58\u5728\u200b\u7684\u200b\u6587\u4ef6\u200b\uff0c\u200b\u9700\u8981\u200b\u4f7f\u7528\u200b\u4e00\u4e2a\u200b\u989d\u5916\u200b\u7684\u200b\u51fd\u6570\u200b <code>creat</code> \u200b\u521b\u5efa\u200b\u6587\u4ef6\u200b\uff0c\u200b\u51fd\u6570\u200b\u539f\u578b\u200b\u5982\u4e0b\u200b:</p> <pre><code>#include &lt;sys/types.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;fcntl.h&gt;\n\nint creat(const char *pathname, mode_t mode);\n</code></pre> <p>\u200b\u8be5\u200b\u51fd\u6570\u200b\u7684\u200b\u4f7f\u7528\u200b\u7b49\u4ef7\u200b\u4e8e\u200b\u73b0\u5728\u200b\u7684\u200b <code>open(pathname, O_WRONLY | O_CREAT | O_TRUNC, mode);</code>\u3002\u200b\u6b64\u200b\u51fd\u6570\u200b\u8fd8\u6709\u200b\u4e00\u4e2a\u200b\u7f3a\u70b9\u200b\uff1a<code>creat</code> \u200b\u51fd\u6570\u200b\u53ea\u80fd\u200b\u4ee5\u200b\u53ea\u200b\u5199\u200b\u65b9\u5f0f\u200b\u6253\u5f00\u200b\u6240\u200b\u521b\u5efa\u200b\u7684\u200b\u6587\u4ef6\u200b\uff0c\u200b\u5982\u679c\u200b\u9700\u8981\u200b\u521b\u5efa\u200b\u4e00\u4e2a\u200b\u4e34\u65f6\u6587\u4ef6\u200b\uff0c\u200b\u5e76\u200b\u8981\u6c42\u200b\u5148\u5199\u200b\u8be5\u200b\u6587\u4ef6\u200b\uff0c\u200b\u7136\u540e\u200b\u53c8\u200b\u8bfb\u200b\u6587\u4ef6\u200b\uff0c\u200b\u5219\u200b\u5fc5\u987b\u200b\u5148\u200b\u8c03\u7528\u200b <code>creat</code>\u3001\u200b\u5199\u5165\u200b\u6570\u636e\u200b\u3001<code>close</code>\uff0c\u200b\u7136\u540e\u200b\u518d\u200b\u8c03\u7528\u200b <code>open</code>\u3001\u200b\u8bfb\u53d6\u6570\u636e\u200b\u3001<code>close</code>\u3002</p>"},{"location":"linux/linux-system-programming/file_io.html#mode-\u53c2\u6570","title":"<code>mode</code> \u200b\u53c2\u6570","text":"<p>\u200b\u5f53\u200b\u4f7f\u7528\u200b <code>O_CREAT</code> \u200b\u521b\u5efa\u200b\u65b0\u200b\u6587\u4ef6\u200b\u65f6\u200b\uff0c<code>mode</code> \u200b\u51b3\u5b9a\u200b\u4e86\u200b\u8be5\u200b\u6587\u4ef6\u200b\u7684\u200b\u8bbf\u95ee\u200b\u6743\u9650\u200b\u3002\u200b\u4f46\u662f\u200b\u6587\u4ef6\u200b\u7684\u200b\u8bbf\u95ee\u200b\u6743\u9650\u200b\u4e0d\u662f\u200b\u6211\u4eec\u200b\u6307\u5b9a\u200b\u7684\u200b <code>mode</code>\uff0c\u200b\u800c\u662f\u200b\u901a\u8fc7\u200b <code>mode &amp; ~umask</code> \u200b\u8ba1\u7b97\u51fa\u6765\u200b\uff0c\u200b\u8fd9\u662f\u200b\u64cd\u4f5c\u7cfb\u7edf\u200b\u4fdd\u62a4\u200b\u7cfb\u7edf\u5b89\u5168\u200b\u7684\u200b\u4e00\u79cd\u200b\u673a\u5236\u200b\u3002</p> <p>\u200b\u4e00\u4e2a\u200b\u8fdb\u7a0b\u200b\u6700\u591a\u200b\u53ef\u200b\u6253\u5f00\u200b\u591a\u5c11\u200b\u6587\u4ef6\u200b\uff1f</p> <p>\u200b\u5728\u200b\u4e0a\u9762\u200b\u8bf4\u200b\u4e86\u200b\u6253\u5f00\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u4f1a\u200b\u5728\u200b\u5185\u5b58\u200b\u4e2d\u200b\u521b\u5efa\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u6765\u200b\u4fdd\u5b58\u200b\u6587\u4ef6\u200b\u7684\u200b\u8fd0\u884c\u200b\u65f6\u200b\u4fe1\u606f\u200b\uff0c\u200b\u65e2\u7136\u200b\u4f1a\u200b\u5360\u7528\u200b\u5185\u5b58\u200b\u8d44\u6e90\u200b\uff0c\u200b\u90a3\u200b\u80af\u5b9a\u200b\u6709\u200b\u4e00\u4e2a\u200b\u4e0a\u9650\u200b\u3002\u200b\u5982\u4e0b\u200b\u6240\u793a\u200b\uff1a</p> <pre><code>#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;sys/types.h&gt;\n\nint main(int argc, char* argv[])\n{\n    int count = 3;  // \u200b\u4ece\u200b 0, 1, 2 \u200b\u5f00\u59cb\u200b\uff0c\u200b\u9884\u7559\u200b\u6807\u51c6\u200b\u8f93\u5165\u200b\u3001\u200b\u8f93\u51fa\u200b\u3001\u200b\u9519\u8bef\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n    while (1)\n    {\n        int fd = open(\"/dev/null\", O_RDONLY);\n        if (fd &lt; 0)\n        {\n            perror(\"open error\");\n            break;\n        }\n\n        count++;\n    }\n\n    printf(\"Max file opens is  %d\\n\", count);\n\n    return 0;\n}\n</code></pre> <p>\u200b\u8f93\u51fa\u200b\u7ed3\u679c\u200b</p> <pre><code>open file failed: Too many open files\nMax file opens is 1024\n</code></pre> <p>\u200b\u5728\u200b\u4e0d\u200b\u66f4\u6539\u200b\u5f53\u524d\u200b\u7cfb\u7edf\u200b\u9ed8\u8ba4\u200b\u7684\u200b\u73af\u5883\u200b\u60c5\u51b5\u200b\u4e0b\u200b\uff0c\u200b\u4e00\u4e2a\u200b\u8fdb\u7a0b\u200b\u6700\u200b\u591a\u200b\u53ef\u4ee5\u200b\u6253\u5f00\u200b 1024 \u200b\u4e2a\u200b\u6587\u4ef6\u200b\u3002\u200b\u6211\u4eec\u200b\u53ef\u4ee5\u200b\u901a\u8fc7\u200b <code>ulimit -a</code> \u200b\u6765\u200b\u67e5\u770b\u200b\u7cfb\u7edf\u200b\u7684\u200b\u6240\u6709\u200b\u8d44\u6e90\u200b\u4f7f\u7528\u200b\u4e0a\u9650\u200b\uff0c\u200b\u5e76\u4e14\u200b\u53ef\u4ee5\u200b\u4f7f\u7528\u200b <code>ulimit -n</code> \u200b\u6765\u200b\u4fee\u6539\u200b\u53ef\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u7684\u200b\u4e0a\u9650\u200b\u3002</p>"},{"location":"linux/linux-system-programming/file_io.html#\u8bfb\u53d6--\u5199\u5165","title":"\u8bfb\u53d6\u200b &amp; \u200b\u5199\u5165","text":"<pre><code>#include &lt;unistd.h&gt;\n\n/**\n * @brief \u200b\u4ece\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u4e2d\u200b\u8bfb\u53d6\u6570\u636e\u200b\n * @param fd    \u200b\u5df2\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param buf   \u200b\u4fdd\u5b58\u200b\u8bfb\u53d6\u6570\u636e\u200b\u7684\u200b\u7f13\u51b2\u533a\u200b\n * @param count \u200b\u671f\u671b\u200b\u8bfb\u53d6\u200b\u7684\u200b\u6700\u5927\u200b\u5b57\u8282\u6570\u200b\n * @return \u200b\u6210\u529f\u200b\u65f6\u200b\u8fd4\u56de\u200b\u5b9e\u9645\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\uff08\u200b\u53ef\u80fd\u200b\u5c0f\u4e8e\u200b count\uff09\n *         \u200b\u8fd4\u56de\u200b 0 \u200b\u8868\u793a\u200b\u5230\u8fbe\u200b\u6587\u4ef6\u200b\u672b\u5c3e\u200b\uff08EOF\uff09\n *         \u200b\u8fd4\u56de\u200b -1 \u200b\u8868\u793a\u200b\u8bfb\u53d6\u200b\u5931\u8d25\u200b\u5e76\u200b\u8bbe\u7f6e\u200b errno\n * \n */\nssize_t read(int fd, void *buf, size_t count);\n\n/**\n * @brief \u200b\u5c06\u200b\u6570\u636e\u200b\u5199\u5165\u200b\u5230\u200b\u5df2\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u4e2d\u200b\n * @param fd    \u200b\u5df2\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param buf   \u200b\u5305\u542b\u200b\u5f85\u200b\u5199\u5165\u200b\u6570\u636e\u200b\u7684\u200b\u7f13\u51b2\u533a\u200b\n * @param count \u200b\u671f\u671b\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n * @return \u200b\u6210\u529f\u200b\u65f6\u200b\u8fd4\u56de\u200b\u5b9e\u9645\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\uff08\u200b\u53ef\u80fd\u200b\u5c0f\u4e8e\u200b count\uff09\uff0c\u200b\u8fd4\u56de\u200b -1 \u200b\u8868\u793a\u200b\u5199\u5165\u200b\u5931\u8d25\u200b\u5e76\u200b\u8bbe\u7f6e\u200b errno\n *  \n */\nssize_t write(int fd, const void *buf, size_t count);\n</code></pre> <p>\u200b\u907f\u5751\u200b\u6307\u5357\u200b\uff1a\u200b\u4e0d\u53ef\u200b\u5ffd\u89c6\u200b\u7684\u200b\u201c\u200b\u77ed\u8bfb\u200b\u201d\u200b\u4e0e\u200b\u201c\u200b\u77ed\u5199\u200b\u201d</p> <p>\u200b\u8fd9\u200b\u4e24\u4e2a\u200b\u51fd\u6570\u200b\u7684\u200b\u57fa\u7840\u200b\u4f7f\u7528\u200b\u770b\u4f3c\u200b\u5f88\u200b\u7b80\u5355\u200b\uff0c\u200b\u4f46\u200b\u5728\u200b\u5b9e\u9645\u200b\u5de5\u7a0b\u200b\u4e2d\u6709\u200b\u4e00\u4e2a\u200b\u5fc5\u987b\u200b\u59a5\u5584\u5904\u7406\u200b\u7684\u200b\u6697\u5751\u200b\uff1a<code>read</code> \u200b\u548c\u200b <code>write</code> \u200b\u8fd4\u56de\u200b\u7684\u200b\u5b9e\u9645\u64cd\u4f5c\u200b\u5b57\u8282\u6570\u200b\u53ef\u80fd\u200b\u4f1a\u200b\u5c0f\u4e8e\u200b\u6211\u4eec\u200b\u8981\u6c42\u200b\u7684\u200b <code>count</code> \u200b\u5927\u5c0f\u200b\u3002\u200b\u8fd9\u79cd\u200b\u73b0\u8c61\u200b\u88ab\u200b\u79f0\u4e3a\u200b \u201c\u200b\u77ed\u8bfb\u200b\u201d\u200b\u6216\u200b\u201c\u200b\u77ed\u5199\u200b\u201d\u3002</p> <p>\u200b\u4ea7\u751f\u200b\u201c\u200b\u77ed\u8bfb\u200b/\u200b\u77ed\u5199\u200b\u201d\u200b\u7684\u200b\u5e38\u89c1\u200b\u539f\u56e0\u200b\u5305\u62ec\u200b\uff1a</p> <ul> <li>\u200b\u9047\u5230\u200b\u6587\u4ef6\u200b\u7ed3\u675f\u7b26\u200b\uff08EOF\uff09\uff1a\u200b\u4f8b\u5982\u200b\u8981\u6c42\u200b\u8bfb\u200b 100 \u200b\u5b57\u8282\u200b\uff0c\u200b\u4f46\u200b\u6587\u4ef6\u200b\u53ea\u200b\u5269\u200b 30 \u200b\u5b57\u8282\u200b\u5c31\u200b\u5230\u200b\u672b\u5c3e\u200b\u4e86\u200b\uff0c\u200b\u6b64\u65f6\u200b\u4f1a\u200b\u8fd4\u56de\u200b 30\u3002</li> <li>\u200b\u64cd\u4f5c\u200b\u7f51\u7edc\u200b\u5957\u200b\u63a5\u5b57\u200b\uff08Socket\uff09\u200b\u548c\u200b\u7ba1\u9053\u200b\uff08Pipe\uff09\uff1a\u200b\u5e95\u5c42\u200b\u7684\u200b\u7f51\u7edc\u200b\u7f13\u51b2\u533a\u200b\u53ef\u80fd\u200b\u6682\u65f6\u200b\u6ca1\u6709\u200b\u8db3\u591f\u200b\u7684\u200b\u6570\u636e\u200b\uff0c\u200b\u6216\u200b\u63a5\u6536\u7aef\u200b\u7684\u200b\u7f13\u51b2\u533a\u200b\u5df2\u6ee1\u200b\uff0c\u200b\u5185\u6838\u200b\u4f1a\u5148\u200b\u8fd4\u56de\u200b\u76ee\u524d\u200b\u80fd\u200b\u5904\u7406\u200b\u7684\u200b\u90e8\u5206\u200b\u3002</li> <li>\u200b\u88ab\u200b\u4fe1\u53f7\u200b\u4e2d\u65ad\u200b\uff08<code>EINTR</code>\uff09\uff1a\u200b\u5728\u200b\u6267\u884c\u200b\u8017\u65f6\u200b\u7684\u200b I/O \u200b\u64cd\u4f5c\u200b\u65f6\u200b\uff0c\u200b\u8fdb\u7a0b\u200b\u53ef\u80fd\u200b\u4f1a\u200b\u6536\u5230\u200b\u7cfb\u7edf\u200b\u7684\u200b\u4fe1\u53f7\u200b\uff08Signal\uff09\u3002\u200b\u5982\u679c\u200b\u4fe1\u53f7\u5904\u7406\u200b\u51fd\u6570\u200b\u8fd4\u56de\u200b\u540e\u200b\uff0cI/O \u200b\u8c03\u7528\u200b\u88ab\u200b\u4e2d\u65ad\u200b\uff0c\u200b\u4f1a\u200b\u8fd4\u56de\u200b -1 \u200b\u5e76\u200b\u5c06\u200b\u9519\u8bef\u7801\u200b <code>ernro</code> \u200b\u8bbe\u7f6e\u200b\u4e3a\u200b <code>EINTR</code>\u3002\u200b\u8fd9\u200b\u4e0d\u662f\u200b\u771f\u6b63\u200b\u7684\u200b\u9519\u8bef\u200b\uff0c\u200b\u800c\u662f\u200b\u7cfb\u7edf\u200b\u5728\u200b\u63d0\u9192\u200b\u4f60\u200b\u201c\u200b\u521a\u521a\u200b\u88ab\u200b\u6253\u65ad\u200b\u4e86\u200b\uff0c\u200b\u8bf7\u200b\u91cd\u8bd5\u200b\u201d\u3002</li> </ul> <p>\u200b\u4e3a\u4e86\u200b\u786e\u4fdd\u200b\u6570\u636e\u200b\u80fd\u591f\u200b\u88ab\u200b\u5b8c\u6574\u200b\u3001\u200b\u53ef\u9760\u200b\u5730\u200b\u8bfb\u53d6\u200b\u4e0e\u200b\u5199\u5165\u200b\uff0c\u200b\u5728\u200b\u5b9e\u9645\u200b\u5de5\u7a0b\u200b\uff08\u200b\u5c24\u5176\u200b\u662f\u200b\u7f51\u7edc\u200b\u7f16\u7a0b\u200b\u4e0e\u200b\u8fdb\u7a0b\u200b\u95f4\u901a\u4fe1\u200b\uff09\u200b\u4e2d\u200b\uff0c\u200b\u6211\u4eec\u200b\u901a\u5e38\u200b\u4e0d\u4f1a\u200b\u76f4\u63a5\u200b\u8c03\u7528\u200b\u539f\u751f\u200b\u7684\u200b <code>read</code>/<code>write</code>\uff0c\u200b\u800c\u662f\u200b\u4f1a\u200b\u81ea\u5df1\u200b\u5c01\u88c5\u200b\u4e00\u4e2a\u200b\u5faa\u73af\u200b\u903b\u8f91\u200b\uff0c\u200b\u5904\u7406\u200b\u597d\u200b\u6307\u9488\u200b\u504f\u79fb\u200b\u548c\u200b\u88ab\u200b\u4fe1\u53f7\u200b\u6253\u65ad\u200b\u7684\u200b\u60c5\u51b5\u200b\u3002\u200b\u4e0b\u9762\u200b\u662f\u200b\u8f83\u4e3a\u200b\u7ecf\u5178\u200b\u7684\u200b <code>readn</code> \u200b\u548c\u200b <code>writen</code> \u200b\u51fd\u6570\u200b\u5b9e\u73b0\u200b\u6a21\u677f\u200b\uff1a</p> <pre><code>#include &lt;unistd.h&gt;\n#include &lt;errno.h&gt;\n\n/**\n * @brief \u200b\u786e\u4fdd\u200b\u8bfb\u53d6\u200b\u5230\u200b\u6307\u5b9a\u200b\u5927\u5c0f\u200b\u7684\u200b\u6570\u636e\u200b\uff0c\u200b\u76f4\u5230\u200b\u8bfb\u6ee1\u200b\u6216\u200b\u9047\u5230\u200b EOF / \u200b\u81f4\u547d\u200b\u9519\u8bef\u200b\n * @param fd    \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param buf   \u200b\u76ee\u6807\u200b\u7f13\u51b2\u533a\u200b\n * @param count \u200b\u9700\u8981\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n * @return \u200b\u5b9e\u9645\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\uff0c\u200b\u53ef\u80fd\u200b\u5c0f\u4e8e\u200b count\uff08EOF\uff09\u200b\u6216\u200b -1\uff08\u200b\u9519\u8bef\u200b\uff09\n *\n */\nssize_t readn(int fd, void* buf, size_t count)\n{\n    if (fd &lt; 0)\n    {\n        return -1;  // \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u9519\u8bef\u200b\u503c\u200b\u9884\u9632\u200b\u5224\u65ad\u200b\n    }\n\n    ssize_t nleft = count;   // \u200b\u5269\u4f59\u200b\u9700\u8981\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n    ssize_t nread = 0;       // \u200b\u6bcf\u6b21\u200b\u5b9e\u9645\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n    char* ptr = (char*)buf;  //  \u200b\u4f7f\u7528\u200b char* \u200b\u6307\u9488\u200b\u4ee5\u4fbf\u200b\u4e8e\u200b\u8fdb\u884c\u200b\u6307\u9488\u200b\u504f\u79fb\u200b\u8ba1\u7b97\u200b\n\n    while (nleft &gt; 0)\n    {\n        nread = read(fd, ptr, nleft);\n        if (nread &lt; 0)\n        {\n            if (errno == EINTR)\n            {\n                nread = 0;  // \u200b\u88ab\u200b\u4fe1\u53f7\u200b\u4e2d\u65ad\u200b\uff0c\u200b\u8fd9\u200b\u4e0d\u7b97\u200b\u9519\u8bef\u200b\uff0c\u200b\u91cd\u65b0\u200b\u8c03\u7528\u200b read\n            }\n            else\n            {\n                return -1;  // \u200b\u53d1\u751f\u200b\u771f\u6b63\u200b\u7684\u200b\u9519\u8bef\u200b\uff0c\u200b\u76f4\u63a5\u200b\u8fd4\u56de\u200b\n            }\n        }\n        else if (nread == 0)\n        {\n            break;  // \u200b\u8bfb\u5230\u200b\u4e86\u200b\u6587\u4ef6\u200b\u672b\u5c3e\u200b EOF\uff0c\u200b\u76f4\u63a5\u200b\u8df3\u51fa\u200b\u5faa\u73af\u200b\n        }\n\n        nleft -= nread;  // \u200b\u66f4\u65b0\u200b\u5269\u4f59\u200b\u5b57\u8282\u6570\u200b\n        ptr += nread;    // \u200b\u7f13\u51b2\u533a\u200b\u6307\u9488\u200b\u5411\u200b\u540e\u200b\u504f\u79fb\u200b\uff0c\u200b\u51c6\u5907\u200b\u4e0b\u200b\u4e00\u6b21\u200b\u63a5\u6536\u200b\n    }\n\n    return count - nleft;\n}\n\n/**\n * @brief \u200b\u786e\u4fdd\u200b\u5c06\u200b\u6307\u5b9a\u200b\u5927\u5c0f\u200b\u7684\u200b\u6570\u636e\u200b\u5168\u90e8\u200b\u5199\u5165\u200b\uff0c\u200b\u76f4\u5230\u200b\u5199\u200b\u5b8c\u200b\u6216\u200b\u9047\u5230\u200b\u81f4\u547d\u200b\u9519\u8bef\u200b\n * @param fd    \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param buf   \u200b\u6e90\u200b\u7f13\u51b2\u533a\u200b\n * @param count \u200b\u9700\u8981\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n * @return \u200b\u5b9e\u9645\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b count\n *\n */\nssize_t readn(int fd, const void* buf, size_t count)\n{\n    if (fd &lt; 0)\n    {\n        return -1;  // \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u9519\u8bef\u200b\u503c\u200b\u9884\u9632\u200b\u5224\u65ad\u200b\n    }\n\n    ssize_t nleft = count;  // \u200b\u5269\u4f59\u200b\u9700\u8981\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n    ssize_t nwrite = 0;     // \u200b\u6bcf\u6b21\u200b\u5b9e\u9645\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n    const char* ptr = (const char*)buf;\n\n    while (nleft &gt; 0)\n    {\n        nwrite = write(fd, ptr, nleft);\n        if (nwrite &lt;= 0)\n        {\n            if (nwrite &lt; 0 &amp;&amp; errno == EINTR)\n            {\n                nwrite = 0;  // \u200b\u88ab\u200b\u4fe1\u53f7\u200b\u4e2d\u65ad\u200b\uff0c\u200b\u91cd\u65b0\u200b\u8c03\u7528\u200b write\n            }\n            else\n            {\n                return -1;  // \u200b\u53d1\u751f\u200b\u771f\u6b63\u200b\u7684\u200b\u9519\u8bef\u200b\n            }\n        }\n\n        nleft -= nwrite;\n        ptr += nwrite;\n    }\n\n    return count;\n}\n</code></pre> <p>\u200b\u6307\u9488\u200b\u5f3a\u5236\u200b\u8f6c\u6362\u200b\u7684\u200b\u5de7\u601d\u200b</p> <p>\u200b\u56e0\u4e3a\u200b C \u200b\u8bed\u8a00\u200b\u4e2d\u200b <code>void *</code> \u200b\u7c7b\u578b\u200b\u7684\u200b\u6307\u9488\u200b\u662f\u200b\u4e0d\u80fd\u200b\u8fdb\u884c\u200b\u52a0\u51cf\u200b\u8fd0\u7b97\u200b\u7684\u200b\uff08\u200b\u7f16\u8bd1\u5668\u200b\u4e0d\u200b\u77e5\u9053\u200b\u8be5\u200b\u7c7b\u578b\u200b\u7684\u200b\u5927\u5c0f\u200b\uff09\uff0c\u200b\u6240\u4ee5\u200b\u5fc5\u987b\u200b\u5f3a\u200b\u8f6c\u4e3a\u200b\u6309\u200b 1 \u200b\u5b57\u8282\u200b\u5bfb\u5740\u200b\u7684\u200b <code>char *</code>\uff0c\u200b\u624d\u80fd\u200b\u5b9e\u73b0\u200b <code>ptr += nread</code>\u3002</p> <p>\u200b\u638c\u63e1\u200b\u4e86\u200b <code>read</code> \u200b\u548c\u200b <code>write</code> \u200b\u7684\u200b\u4f7f\u7528\u200b\u65b9\u5f0f\u200b\uff0c\u200b\u601d\u8003\u200b\u4e00\u4e2a\u200b\u95ee\u9898\u200b\uff1a\u200b\u963b\u585e\u200b\u73b0\u8c61\u200b\u662f\u200b <code>read</code> \u200b\u7684\u200b\u5c5e\u6027\u200b\uff0c\u200b\u8fd8\u662f\u200b\u6587\u4ef6\u200b\u7684\u200b\u5c5e\u6027\u200b\uff1f</p> <p>\u200b\u5728\u200b\u5b9e\u9645\u200b\u6d4b\u8bd5\u200b\u4e2d\u200b\uff0c\u200b\u6211\u4eec\u200b\u53ef\u80fd\u200b\u4f1a\u200b\u53d1\u73b0\u200b\uff1a\u200b\u7528\u200b <code>read</code> \u200b\u53bb\u200b\u8bfb\u200b\u4e00\u4e2a\u200b\u78c1\u76d8\u200b\u4e0a\u200b\u7684\u200b <code>.txt</code> \u200b\u6587\u4ef6\u200b\u65f6\u200b\uff0c\u200b\u77ac\u95f4\u200b\u5c31\u200b\u8fd4\u56de\u200b\u4e86\u200b\uff1b\u200b\u4f46\u7528\u200b <code>read</code> \u200b\u53bb\u200b\u8bfb\u200b\u952e\u76d8\u8f93\u5165\u200b\uff08\u200b\u7ec8\u7aef\u200b\uff09\u200b\u6216\u8005\u200b\u7f51\u7edc\u200b\u6570\u636e\u200b\u65f6\u200b\uff0c\u200b\u7a0b\u5e8f\u200b\u5374\u200b\u5361\u200b\u5728\u200b\u90a3\u91cc\u200b\u4e0d\u52a8\u200b\u4e86\u200b\uff08\u200b\u963b\u585e\u200b\uff09\u3002\u200b\u90a3\u4e48\u200b\uff0c\u200b\u963b\u585e\u200b\u5230\u5e95\u200b\u662f\u200b <code>read</code> \u200b\u51fd\u6570\u200b\u672c\u8eab\u200b\u7684\u200b\u7279\u6027\u200b\uff0c\u200b\u8fd8\u662f\u200b\u6587\u4ef6\u200b\u7684\u200b\u7279\u6027\u200b \u2014\u2014 \u200b\u7ed3\u8bba\u200b\u5f53\u7136\u200b\u662f\u200b\uff1a\u200b\u963b\u585e\u200b\u662f\u200b\u6587\u4ef6\u200b\uff08\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b <code>fd</code>\uff09\u200b\u7684\u200b\u5c5e\u6027\u200b\uff0c\u200b\u800c\u200b\u4e0d\u662f\u200b <code>read</code> \u200b\u51fd\u6570\u200b\u7684\u200b\u5c5e\u6027\u200b\u3002<code>read</code> \u200b\u53ea\u662f\u200b\u6309\u7167\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u7684\u200b\u8bbe\u5b9a\u200b\u884c\u4e8b\u200b\u3002\u200b\u5728\u200b Linux (\u200b\u53c2\u8003\u200b APUE \u200b\u7ecf\u5178\u200b\u7406\u8bba\u200b) \u200b\u4e2d\u200b\uff0c\u200b\u6587\u4ef6\u200b\u88ab\u200b\u9690\u5f0f\u200b\u5730\u200b\u5206\u4e3a\u200b\u4e24\u5927\u7c7b\u200b\uff1a</p> <ul> <li>\u200b\u666e\u901a\u200b\u6587\u4ef6\u200b\uff08Regular Files\uff09\uff1a\u200b\u5bf9\u200b\u78c1\u76d8\u200b\u666e\u901a\u200b\u6587\u4ef6\u200b\u7684\u200b <code>read</code> \u200b\u64cd\u4f5c\u200b\u6c38\u8fdc\u200b\u4e0d\u4f1a\u200b\u88ab\u200b\u89c6\u4e3a\u200b\u963b\u585e\u200b\u3002\u200b\u54ea\u6015\u200b\u8bfb\u53d6\u200b\u9700\u8981\u200b\u82b1\u8d39\u200b\u51e0\u5341\u200b\u6beb\u79d2\u200b\u7b49\u5f85\u200b\u78c1\u76d8\u200b\u8f6c\u52a8\u200b\uff0c\u200b\u5185\u6838\u200b\u4e5f\u200b\u4f1a\u200b\u4fdd\u8bc1\u200b\u5728\u200b\u5408\u7406\u200b\u7684\u200b\u65f6\u95f4\u200b\u5185\u200b\u8fd4\u56de\u200b\u7ed3\u679c\u200b\u3002\u200b\u5982\u679c\u200b\u6587\u4ef6\u200b\u8bfb\u5230\u200b\u4e86\u200b\u5c3d\u5934\u200b\uff0c<code>read</code> \u200b\u4f1a\u200b\u76f4\u63a5\u200b\u8fd4\u56de\u200b 0\uff08EOF\uff09\uff0c\u200b\u7edd\u4e0d\u4f1a\u200b\u5361\u4f4f\u200b\u7b49\u200b\u65b0\u200b\u6570\u636e\u200b\u5199\u5165\u200b\u3002</li> <li>\u200b\u6162\u901f\u200b\u6587\u4ef6\u200b\uff08Slow Files\uff09\uff1a\u200b\u5305\u62ec\u200b\u7ec8\u7aef\u8bbe\u5907\u200b\uff08\u200b\u5982\u200b\u952e\u76d8\u200b\uff09\u3001\u200b\u7ba1\u9053\u200b\uff08Pipe\uff09\u3001FIFO \u200b\u548c\u200b \u200b\u7f51\u7edc\u200b\u5957\u200b\u63a5\u5b57\u200b\uff08Socket\uff09\uff0c\u200b\u8fd9\u4e9b\u200b\u8bbe\u5907\u200b\u7684\u200b\u7279\u70b9\u200b\u662f\u200b\u201c\u200b\u6570\u636e\u200b\u4f55\u65f6\u200b\u5230\u6765\u200b\u662f\u200b\u672a\u77e5\u200b\u7684\u200b\u201d\u3002\u200b\u5f53\u200b\u4f60\u200b\u5bf9\u200b\u4e00\u4e2a\u200b\u6ca1\u6709\u200b\u4efb\u4f55\u200b\u6570\u636e\u200b\u7684\u200b\u6162\u901f\u200b\u6587\u4ef6\u200b\u8c03\u7528\u200b <code>read</code> \u200b\u65f6\u200b\uff0c\u200b\u9ed8\u8ba4\u200b\u60c5\u51b5\u200b\u4e0b\u200b\uff0c\u200b\u5185\u6838\u200b\u4f1a\u200b\u628a\u200b\u5f53\u524d\u200b\u8fdb\u7a0b\u200b\u6302\u200b\u8d77\u200b\uff08\u200b\u6295\u5165\u200b\u7761\u7720\u200b\uff09\uff0c\u200b\u76f4\u5230\u200b\u6709\u200b\u6570\u636e\u200b\u5230\u6765\u200b\u624d\u200b\u5524\u9192\u200b\u5b83\u200b\uff0c\u200b\u8fd9\u200b\u5c31\u662f\u200b\u6211\u4eec\u200b\u5e38\u8bf4\u200b\u7684\u200b\u201c\u200b\u963b\u585e\u200b\u201d\u3002</li> </ul> <p>\u200b\u5373\u4f7f\u200b\u662f\u200b\u9ed8\u8ba4\u200b\u4f1a\u200b\u963b\u585e\u200b\u7684\u200b\u201c\u200b\u6162\u901f\u200b\u6587\u4ef6\u200b\u201d\uff0c\u200b\u6211\u4eec\u200b\u4e5f\u200b\u53ef\u4ee5\u200b\u901a\u8fc7\u200b\u6539\u53d8\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u7684\u200b\u5c5e\u6027\u200b\u6765\u200b\u8ba9\u200b\u5b83\u200b\u53d8\u5f97\u200b\u4e0d\u200b\u963b\u585e\u200b\u3002\u200b\u5982\u679c\u200b\u5728\u200b <code>open</code> \u200b\u8fd9\u4e2a\u200b\u6587\u4ef6\u200b\u65f6\u200b\uff0c\u200b\u6216\u8005\u200b\u4e2d\u9014\u200b\u4f7f\u7528\u200b <code>fcntl</code> \u200b\u51fd\u6570\u200b\uff0c\u200b\u7ed9\u200b\u8fd9\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u52a0\u4e0a\u200b\u4e86\u200b <code>O_NONBLOCK</code>\uff08\u200b\u975e\u200b\u963b\u585e\u200b\uff09 \u200b\u6807\u5fd7\u200b\uff0c\u200b\u90a3\u4e48\u200b <code>read</code> \u200b\u7684\u200b\u884c\u4e3a\u200b\u5c31\u200b\u4f1a\u200b\u53d1\u751f\u200b\u4e0d\u53ef\u601d\u8bae\u200b\u7684\u200b\u53d8\u5316\u200b\uff1a\u200b\u5f53\u200b\u7ba1\u9053\u200b\u6216\u200b\u7f51\u7edc\u200b\u4e2d\u200b\u6ca1\u6709\u200b\u6570\u636e\u200b\u65f6\u200b\uff0c<code>read</code> \u200b\u4e0d\u4f1a\u200b\u518d\u200b\u8ba9\u200b\u8fdb\u7a0b\u200b\u7761\u7720\u200b\u7b49\u5f85\u200b\uff0c\u200b\u800c\u662f\u200b\u4f1a\u200b\u7acb\u523b\u200b\u8fd4\u56de\u200b -1\uff0c\u200b\u5e76\u200b\u5c06\u200b <code>errno</code> \u200b\u8bbe\u7f6e\u200b\u4e3a\u200b <code>EAGAIN</code> \u200b\u6216\u200b <code>EWOULDBLOCK</code>\uff08\u200b\u610f\u601d\u200b\u662f\u200b\uff1a\u200b\u73b0\u5728\u200b\u6ca1\u200b\u6570\u636e\u200b\uff0c\u200b\u8bf7\u200b\u7a0d\u540e\u200b\u518d\u8bd5\u200b\uff09\u3002</p>"},{"location":"linux/linux-system-programming/file_io.html#\u4fee\u6539\u6587\u4ef6\u504f\u79fb\u91cf","title":"\u4fee\u6539\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf","text":"<p>\u200b\u5bf9\u4e8e\u200b\u6bcf\u4e2a\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\uff0c\u200b\u7cfb\u7edf\u200b\u5185\u6838\u200b\u90fd\u200b\u4f1a\u200b\u8bb0\u5f55\u200b\u5176\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\uff0c\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\u662f\u200b\u6307\u4e0b\u200b\u4e00\u4e2a\u200b <code>read</code> \u200b\u548c\u200b <code>write</code> \u200b\u64cd\u4f5c\u200b\u7684\u200b\u6587\u4ef6\u200b\u8d77\u59cb\u200b\u4f4d\u7f6e\u200b\uff0c\u200b\u4f1a\u4ee5\u200b\u76f8\u5bf9\u200b\u4e8e\u200b\u6587\u4ef6\u200b\u5934\u90e8\u200b\u8d77\u59cb\u200b\u70b9\u200b\u7684\u200b\u6587\u4ef6\u200b\u5f53\u524d\u200b\u4f4d\u7f6e\u200b\u6765\u200b\u8868\u793a\u200b\u3002\u200b\u6587\u4ef6\u200b\u6253\u5f00\u200b\u65f6\u200b\uff0c\u200b\u4f1a\u200b\u5c06\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\u8bbe\u7f6e\u200b\u4e3a\u200b\u6307\u5411\u200b\u6587\u4ef6\u200b\u5f00\u59cb\u200b\uff0c\u200b\u4ee5\u540e\u200b\u7684\u200b\u6bcf\u6b21\u200b <code>read</code> \u200b\u548c\u200b <code>write</code> \u200b\u8c03\u7528\u200b\u5c06\u200b\u81ea\u52a8\u200b\u5bf9\u200b\u5176\u200b\u8fdb\u884c\u200b\u8c03\u6574\u200b\uff0c\u200b\u4ee5\u200b\u6307\u5411\u200b\u5df2\u8bfb\u200b\u6216\u200b\u5df2\u200b\u5199\u200b\u6570\u636e\u200b\u540e\u200b\u7684\u200b\u4e0b\u200b\u4e00\u4e2a\u200b\u5b57\u8282\u200b\u3002</p> <pre><code>#include &lt;sys/types.h&gt;\n#include &lt;unistd.h&gt;\n\n/**\n  * @brief \u200b\u6839\u636e\u200b\u6307\u4ee4\u200b whence \u200b\u5c06\u200b\u5df2\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u200b fd \u200b\u7684\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\u91cd\u65b0\u200b\u5b9a\u4f4d\u200b\u5230\u200b\u53c2\u6570\u200b offset \n  * @param fd     \u200b\u5df2\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n  * @param offset \u200b\u76f8\u5bf9\u200b\u8d77\u59cb\u200b\u4f4d\u7f6e\u200b\u7684\u200b\u504f\u79fb\u91cf\u200b\uff08\u200b\u5355\u4f4d\u200b\uff1a\u200b\u5b57\u8282\u200b\uff09\n  * @param whence \u200b\u6307\u5b9a\u200b\u7684\u200b\u8d77\u59cb\u200b\u4f4d\u7f6e\u200b\n  * @return \u200b\u6210\u529f\u200b\u8fd4\u56de\u200b\u504f\u79fb\u200b\u540e\u200b\u7684\u200b\u4f4d\u7f6e\u200b\u4e0e\u200b\u8d77\u59cb\u200b\u4f4d\u7f6e\u200b\u7684\u200b\u8ddd\u79bb\u200b\uff0c\u200b\u5931\u8d25\u200b\u8fd4\u56de\u200b -1\n  *\n  */\noff_t lseek(int fd, off_t offset, int whence);\n</code></pre> <p><code>whence</code> \u200b\u8868\u793a\u200b\u53c2\u7167\u200b\u54ea\u4e2a\u200b\u57fa\u70b9\u200b\u6765\u200b\u8bbe\u7f6e\u200b\u504f\u79fb\u91cf\u200b\uff0c\u200b\u5e94\u4e3a\u200b\u4e0b\u9762\u200b\u4e09\u4e2a\u200b\u4e4b\u4e00\u200b\uff1a</p> <ul> <li><code>SEEK_SET</code>: \u200b\u5c06\u200b\u6587\u4ef6\u200b\u7684\u200b\u504f\u79fb\u91cf\u200b\u8bbe\u7f6e\u200b\u4e3a\u200b\u8ddd\u200b\u6587\u4ef6\u200b\u5f00\u59cb\u200b\u5904\u200b <code>offset</code> \u200b\u4e2a\u200b\u5b57\u8282\u200b</li> <li><code>SEEK_SET</code>: \u200b\u5c06\u200b\u6587\u4ef6\u200b\u7684\u200b\u504f\u79fb\u91cf\u200b\u8bbe\u7f6e\u200b\u4e3a\u200b\u5176\u200b\u5f53\u524d\u200b\u503c\u52a0\u200b <code>offset</code>\uff0c<code>offset</code> \u200b\u53ef\u6b63\u200b\u53ef\u8d1f\u200b</li> <li><code>SEEK_END</code>: \u200b\u5c06\u200b\u6587\u4ef6\u200b\u7684\u200b\u504f\u79fb\u91cf\u200b\u8bbe\u7f6e\u200b\u4e3a\u200b\u8ddd\u200b\u6587\u4ef6\u200b\u957f\u5ea6\u200b\u52a0\u200b <code>offset</code>\uff0c<code>offset</code> \u200b\u53ef\u6b63\u200b\u53ef\u8d1f\u200b</li> </ul> <p>\u200b\u901a\u5e38\u200b\uff0c\u200b\u6587\u4ef6\u200b\u7684\u200b\u5f53\u524d\u200b\u504f\u79fb\u91cf\u200b\u5e94\u5f53\u200b\u662f\u200b\u4e00\u4e2a\u200b\u975e\u8d1f\u200b\u6574\u6570\u200b\uff0c\u200b\u4f46\u662f\u200b\uff0c\u200b\u67d0\u4e9b\u200b\u8bbe\u5907\u200b\u4e5f\u200b\u53ef\u80fd\u200b\u5141\u8bb8\u200b\u8d1f\u200b\u7684\u200b\u504f\u79fb\u91cf\u200b\u3002\u200b\u4f46\u200b\u5bf9\u4e8e\u200b\u666e\u901a\u200b\u6587\u4ef6\u200b\uff0c\u200b\u5176\u200b\u504f\u79fb\u91cf\u200b\u5fc5\u987b\u200b\u662f\u200b\u975e\u8d1f\u503c\u200b\u3002\u200b\u56e0\u4e3a\u200b\u504f\u79fb\u91cf\u200b\u53ef\u80fd\u200b\u662f\u200b\u8d1f\u503c\u200b\uff0c\u200b\u6240\u4ee5\u200b\u5728\u200b\u6bd4\u8f83\u200b <code>lseek</code> \u200b\u7684\u200b\u8fd4\u56de\u503c\u200b\u65f6\u200b\u5e94\u5f53\u200b\u8c28\u614e\u200b\uff0c\u200b\u4e0d\u8981\u200b\u6d4b\u8bd5\u200b\u5b83\u200b\u662f\u5426\u200b\u5c0f\u4e8e\u200b 0\uff0c\u200b\u800c\u200b\u8981\u200b\u6d4b\u8bd5\u200b\u5b83\u200b\u662f\u5426\u200b\u7b49\u4e8e\u200b \u22121\u3002<code>lseek</code> \u200b\u4e0d\u200b\u9002\u7528\u200b\u4e0e\u200b\u6240\u6709\u200b\u7c7b\u578b\u200b\u7684\u200b\u6587\u4ef6\u200b\uff0c\u200b\u4e0d\u5141\u200b\u5c06\u200b <code>lseek</code> \u200b\u5e94\u7528\u200b\u4e8e\u200b\u7ba1\u9053\u200b\u3001FIFO\u3001Socket \u200b\u6216\u8005\u200b\u7ec8\u7aef\u200b\u3002\u200b\u4e00\u65e6\u200b\u5982\u6b64\u200b\uff0c\u200b\u5c31\u200b\u4f1a\u200b\u8fd4\u56de\u200b -1\uff0c\u200b\u5e76\u200b\u5c06\u200b <code>errno</code> \u200b\u7f6e\u200b\u4e3a\u200b <code>ESPIPE</code>\u3002</p> <p><code>lseek</code> \u200b\u8c03\u7528\u200b\u53ea\u662f\u200b\u8c03\u6574\u200b\u5185\u6838\u200b\u4e2d\u200b\u4e0e\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u76f8\u5173\u200b\u7684\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\u8bb0\u5f55\u200b\uff0c\u200b\u5e76\u200b\u6ca1\u6709\u200b\u5f15\u8d77\u200b\u4efb\u4f55\u200b\u7269\u7406\u200b\u8bbe\u5907\u200b\u7684\u200b\u8bbf\u95ee\u200b\u3002\u200b\u7136\u540e\u200b\uff0c\u200b\u8be5\u200b\u504f\u79fb\u91cf\u200b\u7528\u4e8e\u200b\u4e0b\u200b\u4e00\u4e2a\u200b\u8bfb\u200b\u6216\u200b\u5199\u200b\u64cd\u4f5c\u200b\u3002</p> <p>\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\u53ef\u4ee5\u200b\u5927\u4e8e\u200b\u6587\u4ef6\u200b\u7684\u200b\u5f53\u524d\u200b\u957f\u5ea6\u200b\uff0c\u200b\u5728\u200b\u8fd9\u4e2a\u200b\u60c5\u51b5\u200b\u4e0b\u200b\uff0c\u200b\u5bf9\u200b\u8be5\u200b\u6587\u4ef6\u200b\u7684\u200b\u4e0b\u200b\u4e00\u6b21\u200b\u5199\u200b\u5c06\u200b\u52a0\u957f\u200b\u8be5\u200b\u6587\u4ef6\u200b\u5e76\u200b\u5728\u200b\u6587\u4ef6\u200b\u4e2d\u200b\u6784\u6210\u200b\u4e00\u4e2a\u200b\u7a7a\u6d1e\u200b\uff0c\u200b\u8fd9\u200b\u4e00\u70b9\u200b\u662f\u200b\u5141\u8bb8\u200b\u7684\u200b\u3002\u200b\u4f4d\u4e8e\u200b\u6587\u4ef6\u200b\u4e2d\u200b\u4f46\u200b\u6ca1\u6709\u200b\u5199\u8fc7\u200b\u7684\u200b\u5b57\u8282\u200b\u90fd\u200b\u88ab\u200b\u8bfb\u200b\u4e3a\u200b 0\uff08\u200b\u7a7a\u200b\u5b57\u8282\u200b\uff09\u3002\u200b\u6587\u4ef6\u200b\u4e2d\u200b\u7684\u200b\u7a7a\u6d1e\u200b\u5e76\u200b\u4e0d\u200b\u8981\u6c42\u200b\u5728\u200b\u78c1\u76d8\u200b\u4e0a\u200b\u5360\u7528\u200b\u5b9e\u9645\u200b\u5b58\u50a8\u200b\u533a\u200b\u3002\u200b\u5177\u4f53\u200b\u5904\u7406\u65b9\u5f0f\u200b\u4e0e\u200b\u6587\u4ef6\u7cfb\u7edf\u200b\u7684\u200b\u5b9e\u73b0\u200b\u6709\u5173\u200b\uff0c\u200b\u5f53\u200b\u5b9a\u4f4d\u200b\u5230\u200b\u8d85\u51fa\u200b\u6587\u4ef6\u200b\u5c3e\u7aef\u200b\u4e4b\u540e\u200b\u5199\u65f6\u200b\uff0c\u200b\u5bf9\u4e8e\u200b\u65b0\u5199\u200b\u7684\u200b\u6570\u636e\u200b\u9700\u8981\u200b\u5206\u914d\u200b\u78c1\u76d8\u200b\u5757\u200b\uff0c\u200b\u4f46\u662f\u200b\u5bf9\u4e8e\u200b\u539f\u6587\u4ef6\u200b\u5c3e\u7aef\u200b\u548c\u200b\u65b0\u200b\u5f00\u59cb\u200b\u5199\u200b\u4f4d\u7f6e\u200b\u4e4b\u95f4\u200b\u7684\u200b\u90e8\u5206\u200b\u5219\u200b\u4e0d\u200b\u9700\u8981\u200b\u5206\u914d\u200b\u78c1\u76d8\u200b\u5757\u200b\u3002\u200b\u5c3d\u7ba1\u200b\u53ef\u4ee5\u200b\u5b9e\u73b0\u200b 64 \u200b\u4f4d\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\uff0c\u200b\u4f46\u662f\u200b\u80fd\u5426\u200b\u521b\u5efa\u200b\u4e00\u4e2a\u200b\u5927\u4e8e\u200b 2GB(\\(2^{31} - 1\\)) \u200b\u7684\u200b\u6587\u4ef6\u200b\u5219\u200b\u4f9d\u8d56\u4e8e\u200b\u5e95\u5c42\u200b\u6587\u4ef6\u7cfb\u7edf\u200b\u7684\u200b\u7c7b\u578b\u200b\u3002</p> <pre><code>#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;sys/types.h&gt;\n#include &lt;unistd.h&gt;\n\n#define FILE_SIZE (1024L * 1024L * 8)\n\nint main(int argc, char* argv[])\n{\n    int fd = open(argv[1], O_RDWR | O_CREAT, 0644);\n    if (fd &lt; 0)\n    {\n        perror(\"open failed\");\n        return EXIT_FAILURE;\n    }\n\n    if (lseek(fd, FILE_SIZE - 1, SEEK_SET) &lt; 0)\n    {\n        perror(\"lseek failed\");\n        close(fd);\n        return EXIT_FAILURE;\n    }\n\n    write(fd, \"\", 1);\n    close(fd);\n\n    return 0;\n}\n</code></pre> <p>\u200b\u4e0a\u9762\u200b\u7684\u200b\u7a0b\u5e8f\u200b\u521b\u5efa\u200b\u4e86\u200b\u4e00\u4e2a\u200b\u7a7a\u6d1e\u200b\u6587\u4ef6\u200b\uff0c\u200b\u6587\u4ef6\u200b\u4ece\u200b\u7b2c\u200b 0 \u200b\u5b57\u8282\u200b\u5230\u200b\u7b2c\u200b 8388606 \u200b\u5b57\u8282\u200b\u4ece\u672a\u200b\u88ab\u200b\u5199\u5165\u200b\uff0c\u200b\u6587\u4ef6\u7cfb\u7edf\u200b\u4e0d\u4f1a\u200b\u4e3a\u200b\u8fd9\u6bb5\u200b\u7a7a\u6d1e\u200b\u5206\u914d\u200b\u5b9e\u9645\u200b\u7684\u200b\u6570\u636e\u200b\u5757\u200b\uff0c\u200b\u8bfb\u53d6\u200b\u8fd9\u200b\u6bb5\u200b\u533a\u57df\u200b\u65f6\u200b\u5185\u6838\u200b\u4f1a\u200b\u76f4\u63a5\u200b\u8fd4\u56de\u200b\u5168\u96f6\u200b\u3002\u200b\u5728\u200b\u7b2c\u200b 8388607 \u200b\u5b57\u8282\u200b\u5904\u200b\u5199\u5165\u200b 1 \u200b\u5b57\u8282\u200b\uff0c\u200b\u6240\u4ee5\u200b\u6587\u4ef6\u200b\u7684\u200b\u903b\u8f91\u200b\u5927\u5c0f\u200b\u662f\u200b 8MB\u3002</p> <p>\u200b\u7528\u200b <code>ls -lh</code> \u200b\u548c\u200b <code>du -sh</code> \u200b\u53ef\u4ee5\u200b\u76f4\u89c2\u200b\u770b\u5230\u200b\u5dee\u5f02\u200b\uff1a</p> <pre><code>ls -lh hole-file # \u200b\u903b\u8f91\u200b\u5927\u5c0f\u200b\n-rw-r--r-- 1 jeffery jeffery 8.0M  5\u200b\u6708\u200b 25 00:02 hole-file\n\ndu -sh hole-file  # \u200b\u5b9e\u9645\u200b\u5360\u7528\u200b\u78c1\u76d8\u200b\u5757\u200b\n4.0K    hole-file # \u200b\u53ea\u6709\u200b\u672b\u5c3e\u200b\u90a3\u200b 1 \u200b\u5b57\u8282\u200b\u6240\u5728\u200b\u7684\u200b\u4e00\u4e2a\u200b\u5757\u200b\n</code></pre>"},{"location":"linux/linux-system-programming/file_io.html#\u4f7f\u7528\u793a\u4f8b","title":"\u4f7f\u7528\u200b\u793a\u4f8b","text":""},{"location":"linux/linux-system-programming/file_io.html#\u5b9e\u73b0\u7c7b\u4f3c-cp-\u547d\u4ee4\u7684\u7a0b\u5e8f","title":"\u5b9e\u73b0\u200b\u7c7b\u4f3c\u200b <code>cp</code> \u200b\u547d\u4ee4\u200b\u7684\u200b\u7a0b\u5e8f","text":"<pre><code>#include &lt;errno.h&gt;\n#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;string.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;sys/types.h&gt;\n#include &lt;unistd.h&gt;\n\n#define BUFFER_SIZE 1024\n\n/**\n * @brief \u200b\u786e\u4fdd\u200b\u8bfb\u53d6\u200b\u5230\u200b\u6307\u5b9a\u200b\u5927\u5c0f\u200b\u7684\u200b\u6570\u636e\u200b\uff0c\u200b\u76f4\u5230\u200b\u8bfb\u6ee1\u200b\u6216\u200b\u9047\u5230\u200b EOF / \u200b\u81f4\u547d\u200b\u9519\u8bef\u200b\n * @param fd    \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param buf   \u200b\u76ee\u6807\u200b\u7f13\u51b2\u533a\u200b\n * @param count \u200b\u9700\u8981\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n * @return \u200b\u5b9e\u9645\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\uff0c\u200b\u53ef\u80fd\u200b\u5c0f\u4e8e\u200b count\uff08EOF\uff09\u200b\u6216\u200b -1\uff08\u200b\u9519\u8bef\u200b\uff09\n *\n */\nssize_t readn(int fd, void* buf, size_t count);\n\n/**\n * @brief \u200b\u786e\u4fdd\u200b\u5c06\u200b\u6307\u5b9a\u200b\u5927\u5c0f\u200b\u7684\u200b\u6570\u636e\u200b\u5168\u90e8\u200b\u5199\u5165\u200b\uff0c\u200b\u76f4\u5230\u200b\u5199\u200b\u5b8c\u200b\u6216\u200b\u9047\u5230\u200b\u81f4\u547d\u200b\u9519\u8bef\u200b\n * @param fd    \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param buf   \u200b\u6e90\u200b\u7f13\u51b2\u533a\u200b\n * @param count \u200b\u9700\u8981\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n * @return \u200b\u5b9e\u9645\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b count\n *\n */\nssize_t writen(int fd, const void* buf, size_t count);\n\nint main(int argc, char* argv[])\n{\n    if (argc &lt; 3)\n    {\n        fprintf(stderr, \"Usage: %s &lt;source&gt; &lt;destination&gt;\\n\", argv[0]);\n        return EXIT_FAILURE;\n    }\n\n    int sfd = open(argv[1], O_RDONLY);\n    if (sfd &lt; 0)\n    {\n        perror(\"open source\");\n        return EXIT_FAILURE;\n    }\n\n    int dfd = open(argv[2], O_WRONLY | O_CREAT | O_TRUNC, 0644);\n    if (dfd &lt; 0)\n    {\n        perror(\"open destination\");\n        close(sfd);\n        return EXIT_FAILURE;\n    }\n\n    char buffer[BUFFER_SIZE];\n    printf(\"Copying from %s to %s...\\n\", argv[1], argv[2]);\n\n    ssize_t rlen = 0;\n    while ((rlen = readn(sfd, buffer, BUFFER_SIZE)) &gt; 0)\n    {\n        if (writen(dfd, buffer, rlen) != rlen)\n        {\n            perror(\"write error\");\n            close(sfd);\n            close(dfd);\n            return EXIT_FAILURE;\n        }\n    }\n\n    if (rlen &lt; 0)\n    {\n        perror(\"read error\");\n        close(sfd);\n        close(dfd);\n        return EXIT_FAILURE;\n    }\n\n    printf(\"Copy completed.\\n\");\n\n    close(dfd);\n    close(sfd);\n    return 0;\n}\n\nssize_t readn(int fd, void* buf, size_t count)\n{\n    if (fd &lt; 0)\n    {\n        return -1;  // \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u9519\u8bef\u200b\u503c\u200b\u9884\u9632\u200b\u5224\u65ad\u200b\n    }\n\n    ssize_t nleft = count;   // \u200b\u5269\u4f59\u200b\u9700\u8981\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n    ssize_t nread = 0;       // \u200b\u6bcf\u6b21\u200b\u5b9e\u9645\u200b\u8bfb\u53d6\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n    char* ptr = (char*)buf;  //  \u200b\u4f7f\u7528\u200b char* \u200b\u6307\u9488\u200b\u4ee5\u4fbf\u200b\u4e8e\u200b\u8fdb\u884c\u200b\u6307\u9488\u200b\u504f\u79fb\u200b\u8ba1\u7b97\u200b\n\n    while (nleft &gt; 0)\n    {\n        nread = read(fd, ptr, nleft);\n        if (nread &lt; 0)\n        {\n            if (errno == EINTR)\n            {\n                nread = 0;  // \u200b\u88ab\u200b\u4fe1\u53f7\u200b\u4e2d\u65ad\u200b\uff0c\u200b\u8fd9\u200b\u4e0d\u7b97\u200b\u9519\u8bef\u200b\uff0c\u200b\u91cd\u65b0\u200b\u8c03\u7528\u200b read\n            }\n            else\n            {\n                return -1;  // \u200b\u53d1\u751f\u200b\u771f\u6b63\u200b\u7684\u200b\u9519\u8bef\u200b\uff0c\u200b\u76f4\u63a5\u200b\u8fd4\u56de\u200b\n            }\n        }\n        else if (nread == 0)\n        {\n            break;  // \u200b\u8bfb\u5230\u200b\u4e86\u200b\u6587\u4ef6\u200b\u672b\u5c3e\u200b EOF\uff0c\u200b\u76f4\u63a5\u200b\u8df3\u51fa\u200b\u5faa\u73af\u200b\n        }\n\n        nleft -= nread;  // \u200b\u66f4\u65b0\u200b\u5269\u4f59\u200b\u5b57\u8282\u6570\u200b\n        ptr += nread;    // \u200b\u7f13\u51b2\u533a\u200b\u6307\u9488\u200b\u5411\u200b\u540e\u200b\u504f\u79fb\u200b\uff0c\u200b\u51c6\u5907\u200b\u4e0b\u200b\u4e00\u6b21\u200b\u63a5\u6536\u200b\n    }\n\n    return count - nleft;\n}\n\nssize_t writen(int fd, const void* buf, size_t count)\n{\n    if (fd &lt; 0)\n    {\n        return -1;  // \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u9519\u8bef\u200b\u503c\u200b\u9884\u9632\u200b\u5224\u65ad\u200b\n    }\n\n    ssize_t nleft = count;  // \u200b\u5269\u4f59\u200b\u9700\u8981\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n    ssize_t nwrite = 0;     // \u200b\u6bcf\u6b21\u200b\u5b9e\u9645\u200b\u5199\u5165\u200b\u7684\u200b\u5b57\u8282\u6570\u200b\n    const char* ptr = (const char*)buf;\n\n    while (nleft &gt; 0)\n    {\n        nwrite = write(fd, ptr, nleft);\n        if (nwrite &lt;= 0)\n        {\n            if (nwrite &lt; 0 &amp;&amp; errno == EINTR)\n            {\n                nwrite = 0;  // \u200b\u88ab\u200b\u4fe1\u53f7\u200b\u4e2d\u65ad\u200b\uff0c\u200b\u91cd\u65b0\u200b\u8c03\u7528\u200b write\n            }\n            else\n            {\n                return -1;  // \u200b\u53d1\u751f\u200b\u771f\u6b63\u200b\u7684\u200b\u9519\u8bef\u200b\n            }\n        }\n\n        nleft -= nwrite;\n        ptr += nwrite;\n    }\n\n    return count;\n}\n</code></pre>"},{"location":"linux/linux-system-programming/file_io.html#\u83b7\u53d6\u6587\u4ef6\u5927\u5c0f","title":"\u83b7\u53d6\u200b\u6587\u4ef6\u5927\u5c0f","text":"<pre><code>#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;string.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;sys/types.h&gt;\n#include &lt;unistd.h&gt;\n\nint main(int argc, char* argv[])\n{\n    if (argc != 2)\n    {\n        fprintf(stderr, \"Usage: %s &lt;filename&gt;\\n\", argv[0]);\n        return EXIT_FAILURE;\n    }\n\n    int fd = open(argv[1], O_RDONLY);\n    if (fd &lt; 0)\n    {\n        perror(\"open error\");\n        return EXIT_FAILURE;\n    }\n\n    off_t filesize = lseek(fd, 0, SEEK_END);\n    if (filesize &lt; 0)\n    {\n        perror(\"lseek error\");\n        close(fd);\n        return EXIT_FAILURE;\n    }\n\n    printf(\"File size: %ld bytes\\n\", filesize);\n    close(fd);\n\n    return 0;\n}\n</code></pre>"},{"location":"linux/linux-system-programming/file_io.html#\u5b9e\u73b0\u7c7b\u4f3c-tee-\u547d\u4ee4\u7684\u7a0b\u5e8f","title":"\u5b9e\u73b0\u200b\u7c7b\u4f3c\u200b <code>tee</code> \u200b\u547d\u4ee4\u200b\u7684\u200b\u7a0b\u5e8f","text":"<pre><code>#include &lt;errno.h&gt;\n#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;string.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;sys/types.h&gt;\n#include &lt;unistd.h&gt;\n\n#define BUFFER_SIZE 1024\n\nssize_t writen(int fd, const void* buf, size_t count);\n\nint main(int argc, char* argv[])\n{\n    // \u200b\u5148\u200b\u628a\u200b\u6240\u6709\u200b\u8f93\u51fa\u200b\u6587\u4ef6\u200b\u6253\u5f00\u200b\uff0c\u200b\u786e\u4fdd\u200b\u5728\u200b\u8bfb\u53d6\u200b\u6807\u51c6\u200b\u8f93\u5165\u200b\u4e4b\u524d\u200b\u5c31\u200b\u80fd\u200b\u6210\u529f\u200b\u6253\u5f00\u200b\u6240\u6709\u200b\u76ee\u6807\u200b\u6587\u4ef6\u200b\n    int fds[argc - 1];\n    for (int i = 1; i &lt; argc; i++)\n    {\n        fds[i - 1] = open(argv[i], O_WRONLY | O_CREAT | O_TRUNC, 0644);\n        if (fds[i - 1] &lt; 0)\n        {\n            fprintf(stderr, \"open %s failed: %s\\n\", argv[i], strerror(errno));\n            return EXIT_FAILURE;\n        }\n    }\n\n    char buf[BUFFER_SIZE] = {0};\n    int rlen = 0;\n    // \u200b\u4ece\u200b\u6807\u51c6\u200b\u8f93\u5165\u200b\u8bfb\u53d6\u6570\u636e\u200b\n    while ((rlen = read(STDIN_FILENO, buf, BUFFER_SIZE)) &gt; 0)\n    {\n        // \u200b\u5148\u5199\u200b\u5230\u200b\u6807\u51c6\u200b\u8f93\u51fa\u200b\n        if (writen(STDOUT_FILENO, buf, rlen) != rlen)\n        {\n            perror(\"write error\");\n            return EXIT_FAILURE;\n        }\n\n        // \u200b\u5199\u200b\u5230\u200b\u6bcf\u4e2a\u200b\u76ee\u6807\u200b\u6587\u4ef6\u200b\n        for (int i = 0; i &lt; argc - 1; i++)\n        {\n            if (writen(fds[i], buf, rlen) != rlen)\n            {\n                perror(\"write error\");\n                return EXIT_FAILURE;\n            }\n        }\n    }\n\n    if (rlen &lt; 0)\n    {\n        perror(\"read error\");\n        return EXIT_FAILURE;\n    }\n\n    // \u200b\u5199\u200b\u5b8c\u200b\u5173\u95ed\u200b\u6240\u6709\u200b\u4e3b\u52a8\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n    for (int i = 0; i &lt; argc - 1; i++)\n    {\n        close(fds[i]);\n    }\n\n    return 0;\n}\n\nssize_t writen(int fd, const void* buf, size_t count)\n{\n    if (fd &lt; 0)\n    {\n        errno = EINVAL;\n        return -1;\n    }\n\n    ssize_t nleft = count;\n    ssize_t nwrite = 0;\n    const char* ptr = (const char*)buf;\n\n    while (nleft &gt; 0)\n    {\n        nwrite = write(fd, ptr, nleft);\n        if (nwrite &lt;= 0)\n        {\n            if (nwrite &lt; 0 &amp;&amp; errno == EINTR)\n            {\n                nwrite = 0;\n            }\n            else\n            {\n                return -1;\n            }\n        }\n\n        nleft -= nwrite;\n        ptr += nwrite;\n    }\n\n    return count;\n}\n</code></pre>"},{"location":"linux/linux-system-programming/file_io.html#\u6587\u4ef6\u5171\u4eab","title":"\u6587\u4ef6\u5171\u4eab","text":"<p>UNIX/Linux \u200b\u7cfb\u7edf\u200b\u652f\u6301\u200b\u6587\u4ef6\u200b\u5728\u200b\u4e0d\u540c\u200b\u7684\u200b\u8fdb\u7a0b\u200b\u95f4\u200b\u5171\u4eab\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\uff0c\u200b\u5171\u4eab\u200b\u6587\u4ef6\u200b\u672c\u8d28\u200b\u4e0a\u200b\u662f\u200b\u7814\u7a76\u200b\u5185\u6838\u200b\u5982\u4f55\u200b\u7ba1\u7406\u200b\u5df2\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u3002\u200b\u5185\u6838\u200b\u4f7f\u7528\u200b\u4e09\u79cd\u200b\u6570\u636e\u7ed3\u6784\u200b\u8868\u793a\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\uff0c\u200b\u4ed6\u4eec\u200b\u4e4b\u95f4\u200b\u7684\u200b\u5173\u7cfb\u200b\u51b3\u5b9a\u200b\u4e86\u200b\u5728\u200b\u6587\u4ef6\u5171\u4eab\u200b\u65b9\u9762\u200b\u4e00\u4e2a\u200b\u8fdb\u7a0b\u200b\u5bf9\u200b\u53e6\u200b\u4e00\u4e2a\u200b\u8fdb\u7a0b\u200b\u53ef\u80fd\u200b\u4ea7\u751f\u200b\u7684\u200b\u5f71\u54cd\u200b\u3002</p> <p>\u200b\u4e09\u79cd\u200b\u6570\u636e\u7ed3\u6784\u200b\u662f\u200b\u4ec0\u4e48\u200b\uff1a </p> <ol> <li>\u200b\u8fdb\u7a0b\u200b\u7ea7\u200b\uff1a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u8868\u200b (File Descriptor Table)<ul> <li>\u200b\u6bcf\u4e2a\u200b\u8fdb\u7a0b\u200b\u5728\u200b\u8fdb\u7a0b\u200b\u63a7\u5236\u200b\u5757\u200b\u4e2d\u200b\u90fd\u200b\u6709\u200b\u4e00\u4e2a\u200b\u8bb0\u5f55\u200b\u9879\u200b\uff0c\u200b\u8bb0\u5f55\u200b\u9879\u4e2d\u200b\u5305\u542b\u200b\u4e00\u5f20\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u8868\u200b</li> <li>\u200b\u8868\u4e2d\u200b\u7684\u200b\u6bcf\u4e00\u9879\u200b\u5305\u542b\u200b\uff1a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6807\u5fd7\u200b\u548c\u200b\u4e00\u4e2a\u200b\u6307\u5411\u200b\u7cfb\u7edf\u200b\u7ea7\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u8868\u8fbe\u200b\u7684\u200b\u6307\u9488\u200b</li> </ul> </li> <li>\u200b\u7cfb\u7edf\u200b\u7ea7\u200b\uff1a\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u8868\u200b (Open File Table)<ul> <li>\u200b\u5185\u6838\u200b\u4e3a\u200b\u6240\u6709\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u7ef4\u62a4\u200b\u7684\u200b\u4e00\u5f20\u200b\u5168\u5c40\u200b\u8868\u200b\uff0c\u200b\u8868\u4e2d\u200b\u7684\u200b\u6bcf\u4e00\u9879\u200b\u79f0\u4e3a\u200b\u201c\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u201d</li> <li>\u200b\u6bcf\u4e2a\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u5305\u542b\u200b\uff1a\u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\uff08<code>O_RDONLY</code>, <code>O_APPEND</code> \u200b\u7b49\u200b\uff09\u3001\u200b\u5f53\u524d\u200b\u7684\u200b\u8bfb\u5199\u200b\u504f\u79fb\u91cf\u200b\uff08\u200b\u5373\u200b\u5149\u6807\u200b\u4f4d\u7f6e\u200b <code>offset</code>\uff09\u200b\u4ee5\u53ca\u200b\u6307\u5411\u200b Inode \u200b\u8868\u200b\u7684\u200b\u6307\u9488\u200b</li> </ul> </li> <li>\u200b\u6587\u4ef6\u7cfb\u7edf\u200b\u7ea7\u200b\uff1a\u200b\u7d22\u5f15\u200b\u8282\u70b9\u200b\u8868\u200b\uff08Inode Table\uff09<ul> <li>\u200b\u6bcf\u4e2a\u200b\u5b9e\u9645\u200b\u5b58\u5728\u200b\u4e8e\u200b\u78c1\u76d8\u200b\u7684\u200b\u6587\u4ef6\u200b\uff0c\u200b\u5728\u200b\u5185\u5b58\u200b\u4e2d\u200b\u90fd\u200b\u6709\u200b\u552f\u4e00\u200b\u7684\u200b\u4e00\u4e2a\u200b Inode \u200b\u8282\u70b9\u200b</li> <li>\u200b\u5b83\u200b\u4fdd\u5b58\u200b\u4e86\u200b\u6587\u4ef6\u200b\u7684\u200b\u56fa\u6709\u200b\u5c5e\u6027\u200b\uff1a\u200b\u6587\u4ef6\u5927\u5c0f\u200b\u3001\u200b\u6240\u6709\u8005\u200b\u6743\u9650\u200b\u4ee5\u53ca\u200b\u6570\u636e\u200b\u5728\u200b\u78c1\u76d8\u200b\u4e0a\u200b\u7684\u200b\u7269\u7406\u200b\u4f4d\u7f6e\u200b</li> </ul> </li> </ol> <p>\u200b\u4e0b\u9762\u200b\u662f\u200b\u4e00\u4e2a\u200b\u8fdb\u7a0b\u200b\u5bf9\u5e94\u200b\u7684\u200b\u4e09\u79cd\u200b\u6570\u636e\u7ed3\u6784\u200b\u4e4b\u95f4\u200b\u7684\u200b\u5173\u7cfb\u200b\uff0c\u200b\u8be5\u200b\u8fdb\u7a0b\u200b\u6709\u200b\u4e24\u4e2a\u200b\u4e0d\u540c\u200b\u7684\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\uff1a\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u4ece\u200b\u6807\u51c6\u200b\u8f93\u5165\u200b\u6253\u5f00\u200b\uff0c\u200b\u53e6\u200b\u4e00\u4e2a\u200b\u4ece\u200b\u6807\u51c6\u200b\u8f93\u51fa\u200b\u6253\u5f00\u200b\u3002</p> <p></p> <p>\u200b\u5982\u679c\u200b\u662f\u200b\u5728\u200b\u4e24\u4e2a\u200b\u4e0d\u540c\u200b\u7684\u200b\u8fdb\u7a0b\u200b\u4e2d\u200b\u6253\u5f00\u200b\uff0c\u200b\u4e5f\u200b\u53ef\u4ee5\u200b\u6253\u5f00\u200b\u540c\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\uff0c\u200b\u5982\u4e0b\u200b\u6240\u793a\u200b</p> <p></p> <p>\u200b\u53ef\u80fd\u200b\u4f1a\u200b\u6709\u200b\u591a\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6307\u5411\u200b\u540c\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\uff0c\u200b\u6bd4\u5982\u200b <code>dup</code> \u200b\u51fd\u6570\u200b\uff0c\u200b\u5c31\u200b\u80fd\u200b\u770b\u5230\u200b\u8fd9\u200b\u4e00\u70b9\u200b\u3002\u200b\u5728\u200b <code>fork</code> \u200b\u4e4b\u540e\u200b\u4e5f\u200b\u4f1a\u200b\u53d1\u751f\u200b\u76f8\u540c\u200b\u7684\u200b\u60c5\u51b5\u200b\uff0c\u200b\u6b64\u65f6\u200b\u7236\u200b\u8fdb\u7a0b\u200b\u3001\u200b\u5b50\u200b\u8fdb\u7a0b\u200b\u5404\u81ea\u200b\u7684\u200b\u6bcf\u200b\u4e00\u4e2a\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u5171\u4eab\u200b\u540c\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u3002\u200b\u5bf9\u4e8e\u200b\u591a\u4e2a\u200b\u8fdb\u7a0b\u200b\u8bfb\u53d6\u200b\u540c\u4e00\u200b\u6587\u4ef6\u200b\u90fd\u200b\u80fd\u200b\u6b63\u786e\u200b\u5de5\u4f5c\u200b\uff0c\u200b\u662f\u56e0\u4e3a\u200b\u6bcf\u4e2a\u200b\u8fdb\u7a0b\u200b\u90fd\u200b\u6709\u200b\u5b83\u200b\u81ea\u5df1\u200b\u7684\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\uff0c\u200b\u5176\u4e2d\u200b\u4e5f\u200b\u6709\u200b\u5b83\u200b\u81ea\u5df1\u200b\u7684\u200b\u5f53\u524d\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\u3002\u200b\u4f46\u662f\u200b\uff0c\u200b\u5f53\u200b\u591a\u4e2a\u200b\u8fdb\u7a0b\u200b\u5199\u200b\u540c\u4e00\u200b\u6587\u4ef6\u200b\u65f6\u200b\uff0c\u200b\u5219\u200b\u53ef\u80fd\u200b\u4ea7\u751f\u200b\u9884\u60f3\u200b\u4e0d\u5230\u200b\u7684\u200b\u7ed3\u679c\u200b\u3002\u200b\u4e3a\u4e86\u200b\u8bf4\u660e\u200b\u5982\u4f55\u200b\u907f\u514d\u200b\u8fd9\u79cd\u200b\u60c5\u51b5\u200b\uff0c\u200b\u9700\u8981\u200b\u7406\u89e3\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b\u3002</p> <p>\u200b\u5f53\u200b\u5176\u4e2d\u200b\u4e00\u4e2a\u200b <code>fd</code> \u200b\u88ab\u200b <code>close</code> \u200b\u65f6\u200b\uff0c\u200b\u80fd\u5426\u200b\u7acb\u5373\u200b\u91ca\u653e\u200b\u5b83\u200b\u5bf9\u5e94\u200b\u7684\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b</p> <p>\u200b\u7b54\u6848\u200b\u662f\u200b\u4e0d\u80fd\u200b\uff0c\u200b\u5426\u5219\u200b\u5176\u4ed6\u200b\u4ecd\u7136\u200b\u6307\u5411\u200b\u8be5\u200b\u8868\u9879\u200b\u7684\u200b <code>fd</code> \u200b\u4f1a\u200b\u56e0\u6b64\u200b\u53d8\u6210\u200b\u60ac\u7a7a\u200b\u5f15\u7528\u200b\u3002</p> <p>\u200b\u5185\u6838\u200b\u901a\u8fc7\u200b\u5f15\u7528\u200b\u8ba1\u6570\u200b\u6765\u200b\u89e3\u51b3\u200b\u8fd9\u4e2a\u200b\u95ee\u9898\u200b\u3002<code>struct file</code> \u200b\u5185\u90e8\u200b\u7ef4\u62a4\u200b\u4e00\u4e2a\u200b\u8ba1\u6570\u5668\u200b <code>f_count</code>\uff0c\u200b\u6bcf\u5f53\u200b\u6709\u200b\u65b0\u200b\u7684\u200b <code>fd</code> \u200b\u6307\u5411\u200b\u8be5\u200b\u8868\u9879\u200b\u65f6\u200b\u8ba1\u6570\u200b\u52a0\u200b 1\uff0c<code>close</code> \u200b\u65f6\u200b\u8ba1\u6570\u200b\u51cf\u200b 1\uff0c\u200b\u53ea\u6709\u200b\u5f53\u200b\u8ba1\u6570\u200b\u5f52\u200b\u96f6\u65f6\u200b\u624d\u200b\u771f\u6b63\u200b\u91ca\u653e\u200b\u8be5\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u7684\u200b\u5185\u5b58\u200b\u3002</p> <p>\u200b\u56e0\u6b64\u200b\uff0c<code>fork</code> \u200b\u540e\u82e5\u5b50\u200b\u8fdb\u7a0b\u200b\u4e0d\u518d\u200b\u9700\u8981\u200b\u4ece\u7236\u200b\u8fdb\u7a0b\u200b\u7ee7\u627f\u200b\u7684\u200b\u67d0\u4e9b\u200b <code>fd</code>\uff0c\u200b\u5e94\u5f53\u200b\u663e\u5f0f\u200b\u8c03\u7528\u200b <code>close</code> \u200b\u5173\u95ed\u200b\uff0c\u200b\u5426\u5219\u200b\u5373\u4f7f\u200b\u7236\u200b\u8fdb\u7a0b\u200b\u5df2\u7ecf\u200b\u5173\u95ed\u200b\uff0c\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u7684\u200b\u5f15\u7528\u200b\u8ba1\u6570\u200b\u4ecd\u200b\u4e0d\u200b\u4e3a\u200b\u96f6\u200b\uff0c\u200b\u76f8\u5173\u200b\u8d44\u6e90\u200b\u4e0d\u4f1a\u200b\u88ab\u200b\u91ca\u653e\u200b\uff0c\u200b\u53ef\u80fd\u200b\u5bfc\u81f4\u200b\u8d44\u6e90\u200b\u6cc4\u6f0f\u200b\u6216\u200b\u7ba1\u9053\u200b\u5199\u7aef\u200b\u65e0\u6cd5\u200b\u5173\u95ed\u200b\u7b49\u200b\u95ee\u9898\u200b\u3002</p>"},{"location":"linux/linux-system-programming/file_io.html#\u539f\u5b50\u64cd\u4f5c","title":"\u539f\u5b50\u200b\u64cd\u4f5c","text":"<p>\u200b\u5f53\u200b\u6211\u4eec\u200b\u9700\u8981\u200b\u5c06\u200b\u6570\u636e\u200b\u8ffd\u52a0\u200b\u5230\u200b\u6587\u4ef6\u200b\u672b\u200b\uff0c\u200b\u7a0b\u5e8f\u200b\u53ef\u80fd\u200b\u4f1a\u200b\u5b9e\u73b0\u200b\u6210\u200b\u4e0b\u9762\u200b\u7684\u200b\u5f62\u5f0f\u200b\uff1a</p> <pre><code>if (lseek(fd, 0, SEEK_END) == -1) {\n    perror(\"lseek error\");\n    return EXIT_FAILURE;\n}\n\nif (wirte(fd, buf, rlen) &lt;= 0) {\n    perror(\"write error\");\n    return EXIT_FAILURE;\n}\n</code></pre> <p>\u200b\u5bf9\u200b\u5355\u4e2a\u200b\u8fdb\u7a0b\u200b\u800c\u8a00\u200b\uff0c\u200b\u8fd9\u200b\u6bb5\u7a0b\u5e8f\u200b\u80fd\u200b\u6b63\u5e38\u200b\u5de5\u4f5c\u200b\uff0c\u200b\u4f46\u200b\u82e5\u200b\u6709\u200b\u591a\u4e2a\u200b\u8fdb\u7a0b\u200b\u540c\u65f6\u200b\u4f7f\u7528\u200b\u8fd9\u4e2a\u200b\u65b9\u6cd5\u200b\u5c06\u200b\u6570\u636e\u200b\u8ffd\u52a0\u200b\u5199\u200b\u5230\u200b\u540c\u4e00\u200b\u6587\u4ef6\u200b\uff0c\u200b\u5219\u200b\u4f1a\u200b\u4ea7\u751f\u200b\u95ee\u9898\u200b\u3002\u200b\u5047\u8bbe\u200b\u4e24\u4e2a\u200b\u72ec\u7acb\u200b\u7684\u200b\u8fdb\u7a0b\u200b A \u200b\u548c\u200b B \u200b\u90fd\u200b\u5bf9\u200b\u540c\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u8fdb\u884c\u200b\u8ffd\u52a0\u200b\u5199\u200b\u64cd\u4f5c\u200b\u3002\u200b\u6bcf\u4e2a\u200b\u8fdb\u7a0b\u200b\u90fd\u200b\u5df2\u200b\u6253\u5f00\u200b\u4e86\u200b\u8be5\u200b\u6587\u4ef6\u200b\uff0c\u200b\u4f46\u200b\u672a\u200b\u4f7f\u7528\u200b <code>O_APPEND</code> \u200b\u6807\u5fd7\u200b\u3002\u200b\u6bcf\u4e2a\u200b\u8fdb\u7a0b\u200b\u90fd\u200b\u6709\u200b\u5b83\u200b\u81ea\u5df1\u200b\u7684\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\uff0c\u200b\u4f46\u200b\u5171\u4eab\u200b\u4e00\u4e2a\u200b inode \u200b\u8282\u70b9\u200b\u8868\u9879\u200b\u3002\u200b\u5047\u5b9a\u200b\u8fdb\u7a0b\u200b A \u200b\u8c03\u7528\u200b\u4e86\u200b <code>lseek</code>\uff0c\u200b\u5b83\u200b\u5c06\u200b\u81ea\u5df1\u200b\u7684\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u7684\u200b\u504f\u79fb\u91cf\u200b\u8bbe\u7f6e\u200b\u4e3a\u200b 1500 \u200b\u5b57\u8282\u200b\u5904\u200b\uff08\u200b\u6587\u4ef6\u200b\u672b\u5c3e\u200b\uff09\u3002\u200b\u7136\u540e\u200b\u5185\u6838\u200b\u5207\u6362\u200b\u8fdb\u7a0b\u200b\uff0c\u200b\u8fdb\u7a0b\u200b B \u200b\u5f00\u59cb\u200b\u8c03\u7528\u200b <code>lseek</code>\uff0c\u200b\u4e5f\u200b\u5c06\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u7684\u200b\u504f\u79fb\u91cf\u200b\u8bbe\u7f6e\u200b\u4e3a\u200b 1500 \u200b\u5b57\u8282\u200b\u5904\u200b\uff08\u200b\u6587\u4ef6\u200b\u672b\u5c3e\u200b\uff09\u3002\u200b\u7136\u540e\u200b\u8fdb\u7a0b\u200b B \u200b\u8c03\u7528\u200b <code>write</code> \u200b\u5199\u5165\u200b\u6570\u636e\u200b\uff0c\u200b\u5c06\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\u589e\u52a0\u200b\u81f3\u200b 1600\u3002\u200b\u56e0\u4e3a\u200b\u6587\u4ef6\u200b\u7684\u200b\u957f\u5ea6\u200b\u589e\u52a0\u200b\u4e86\u200b\uff0cinode \u200b\u8282\u70b9\u200b\u8868\u9879\u200b\u5f53\u524d\u200b\u6587\u4ef6\u200b\u957f\u5ea6\u200b\u4e5f\u200b\u66f4\u65b0\u200b\u4e3a\u200b 1600\u3002\u200b\u7136\u540e\u200b\u5185\u6838\u200b\u53c8\u200b\u5207\u6362\u200b\u81f3\u200b\u8fdb\u7a0b\u200b A\uff0c\u200b\u4f7f\u7528\u200b\u8fdb\u7a0b\u200b A \u200b\u6062\u590d\u200b\u8fd0\u884c\u200b\u3002\u200b\u5f53\u200b\u8fdb\u7a0b\u200b A \u200b\u8c03\u7528\u200b <code>write</code> \u200b\u5199\u5165\u200b\u6570\u636e\u200b\u65f6\u200b\uff0c\u200b\u8fd8\u662f\u200b\u4ece\u200b\u5f53\u524d\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\uff081500\uff09\u200b\u5904\u200b\u5f00\u59cb\u200b\u5199\u5165\u200b\u6570\u636e\u200b\uff0c\u200b\u8fd9\u6837\u200b\u5c31\u200b\u8986\u76d6\u200b\u4e86\u200b\u8fdb\u7a0b\u200b B \u200b\u521a\u521a\u200b\u5199\u5165\u200b\u7684\u200b\u6570\u636e\u200b\u3002</p> <p>\u200b\u89e3\u51b3\u200b\u8fd9\u79cd\u200b\u529e\u6cd5\u200b\u5c31\u662f\u200b\u4f7f\u200b\u8fd9\u200b\u4e24\u4e2a\u200b\u64cd\u4f5c\u200b\u79f0\u4e3a\u200b\u4e00\u4e2a\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b\uff0c\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b\u662f\u200b\u4e00\u4e2a\u200b\u4e0d\u53ef\u5206\u5272\u200b\u7684\u200b\u64cd\u4f5c\u200b\uff0c\u200b\u901a\u8fc7\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b\u53ef\u4ee5\u200b\u89e3\u51b3\u200b\u591a\u7ebf\u7a0b\u200b/\u200b\u8fdb\u7a0b\u200b\u4e4b\u95f4\u200b\u7684\u200b\u7ade\u4e89\u200b\u548c\u200b\u51b2\u7a81\u200b\u95ee\u9898\u200b\u3002\u200b\u4e00\u822c\u800c\u8a00\u200b\uff0c\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b\uff08atomic operation\uff09\u200b\u6307\u200b\u7684\u200b\u662f\u200b\u7531\u200b\u591a\u6b65\u200b\u7ec4\u6210\u200b\u7684\u200b\u4e00\u4e2a\u200b\u64cd\u4f5c\u200b\u3002\u200b\u5982\u679c\u200b\u8be5\u200b\u64cd\u4f5c\u200b\u539f\u5b50\u200b\u5730\u200b\u6267\u884c\u200b\uff0c\u200b\u8981\u4e48\u200b\u6267\u884c\u200b\u5b8c\u200b\u6240\u6709\u200b\u6b65\u9aa4\u200b\uff0c\u200b\u8981\u4e48\u200b\u5c31\u200b\u4e00\u6b65\u200b\u4e5f\u200b\u4e0d\u200b\u6267\u884c\u200b\uff0c\u200b\u4e0d\u200b\u53ef\u80fd\u200b\u53ea\u200b\u6267\u884c\u200b\u6240\u6709\u200b\u6b65\u9aa4\u200b\u7684\u200b\u4e00\u4e2a\u200b\u5b50\u96c6\u200b\u3002</p> <p>\u200b\u5728\u200b\u5b9e\u9645\u200b\u5de5\u7a0b\u200b\u4e2d\u200b\uff0c\u200b\u5bf9\u200b <code>open</code> \u200b\u51fd\u6570\u200b\u8bbe\u7f6e\u200b <code>O_CREAT</code> \u200b\u548c\u200b <code>O_EXCL</code> \u200b\u6807\u5fd7\u200b\u4e5f\u200b\u53ef\u4ee5\u200b\u539f\u5b50\u200b\u5224\u65ad\u200b\u5f53\u524d\u200b\u6587\u4ef6\u200b\u662f\u5426\u200b\u5b58\u5728\u200b\uff0c\u200b\u4e0d\u200b\u5b58\u5728\u200b\u5e76\u200b\u521b\u5efa\u200b\u6587\u4ef6\u200b\u3002</p>"},{"location":"linux/linux-system-programming/file_io.html#\u590d\u5236\u6587\u4ef6\u63cf\u8ff0\u7b26","title":"\u590d\u5236\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26","text":"<p>\u200b\u590d\u5236\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u540e\u200b\uff0c\u200b\u65b0\u65e7\u200b\u4e24\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u4f1a\u200b\u6307\u5411\u200b\u5185\u6838\u200b\u4e2d\u200b\u7684\u200b \u200b\u540c\u4e00\u4e2a\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u3002\u200b\u8fd9\u200b\u610f\u5473\u7740\u200b\u5b83\u4eec\u200b \u200b\u5171\u4eab\u200b\u540c\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u504f\u79fb\u91cf\u200b\uff08\u200b\u5149\u6807\u200b\uff09\u200b\u548c\u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\u3002\u200b\u56e0\u6b64\u200b\uff0c\u200b\u901a\u8fc7\u200b\u5176\u4e2d\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u8fdb\u884c\u200b\u8bfb\u5199\u200b\u5f15\u8d77\u200b\u7684\u200b\u5149\u6807\u200b\u79fb\u52a8\u200b\uff0c\u200b\u4f1a\u200b\u76f4\u63a5\u200b\u4f5c\u7528\u200b\u4e8e\u200b\u53e6\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\uff0c\u200b\u5982\u4e0b\u200b\u56fe\u200b\u6240\u793a\u200b\uff1a</p> <p></p> <pre><code>#include &lt;unistd.h&gt;\n\n/**\n * @brief \u200b\u521b\u5efa\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b oldfd \u200b\u7684\u200b\u526f\u672c\u200b\n * @param oldfd \u200b\u5df2\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @return \u200b\u6210\u529f\u200b\u8fd4\u56de\u200b\u65b0\u200b\u7684\u200b\u6700\u5c0f\u200b\u53ef\u7528\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\uff0c\u200b\u5931\u8d25\u200b\u8fd4\u56de\u200b -1\uff0c\u200b\u5e76\u200b\u76f8\u5e94\u200b\u8bbe\u7f6e\u200b errno\n *  \n */\nint dup(int oldfd);\n\n/**\n * @brief \u200b\u5c06\u200b oldfd \u200b\u590d\u5236\u5230\u200b\u6307\u5b9a\u200b\u7684\u200b newfd\n * @param oldfd \u200b\u5df2\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param newfd \u200b\u6307\u5b9a\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u7f16\u53f7\u200b\n * @return \u200b\u6210\u529f\u200b\u8fd4\u56de\u200b\u6307\u5b9a\u200b\u7684\u200b newfd\uff0c\u200b\u5931\u8d25\u200b\u8fd4\u56de\u200b -1 \u200b\u5e76\u200b\u8bbe\u7f6e\u200b errno\n *  \n */\nint dup2(int oldfd, int newfd);\n</code></pre> <p>\u200b\u7531\u200b <code>dup</code> \u200b\u8fd4\u56de\u200b\u7684\u200b\u65b0\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u4e00\u5b9a\u200b\u662f\u200b\u5f53\u524d\u200b\u53ef\u7528\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u4e2d\u200b\u7684\u200b\u6700\u5c0f\u200b\u6570\u503c\u200b\u3002<code>dup2()</code> \u200b\u7cfb\u7edf\u200b\u8c03\u7528\u200b\u6267\u884c\u200b\u7684\u200b\u4efb\u52a1\u200b\u4e0e\u200b <code>dup()</code> \u200b\u76f8\u540c\u200b\uff0c\u200b\u4f46\u200b\u5b83\u200b\u4e0d\u200b\u4f7f\u7528\u200b\u7f16\u53f7\u200b\u6700\u5c0f\u200b\u7684\u200b\u672a\u200b\u4f7f\u7528\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\uff0c\u200b\u800c\u662f\u200b\u4f7f\u7528\u200b <code>newfd</code> \u200b\u4e2d\u200b\u6307\u5b9a\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u7f16\u53f7\u200b\u3002\u200b\u5982\u679c\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b <code>newfd</code> \u200b\u4e4b\u524d\u200b\u5df2\u200b\u6253\u5f00\u200b\uff0c\u200b\u5219\u200b\u5728\u200b\u91cd\u65b0\u200b\u4f7f\u7528\u200b\u4e4b\u524d\u200b\u4f1a\u200b\u9ed8\u9ed8\u200b\u5173\u95ed\u200b\u5b83\u200b\uff0c\u200b\u5173\u95ed\u200b\u548c\u200b\u91cd\u7528\u200b <code>newfd</code> \u200b\u662f\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b\u3002\u200b\u5982\u679c\u200b\u65e7\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u662f\u200b\u4e00\u4e2a\u200b\u65e0\u6548\u200b\u7684\u200b\uff0c\u200b\u5219\u200b\u51fd\u6570\u8c03\u7528\u200b\u4f1a\u200b\u5931\u8d25\u200b\uff0c\u200b\u5e76\u4e14\u200b\u4e0d\u4f1a\u200b\u5173\u95ed\u200b <code>newfd</code>\uff1b\u200b\u5982\u679c\u200b\u65e7\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u662f\u200b\u6709\u6548\u200b\u7684\u200b\uff0c\u200b\u5e76\u4e14\u200b <code>oldfd</code> \u200b\u4e0e\u200b <code>newfd</code> \u200b\u76f8\u540c\u200b\uff0c\u200b\u5219\u200b\u4e0d\u4f1a\u200b\u505a\u200b\u4efb\u4f55\u200b\u4e8b\u200b\uff0c\u200b\u76f4\u63a5\u200b\u8fd4\u56de\u200b <code>newfd</code>\u3002</p> <p>\u200b\u4fdd\u6301\u200b <code>puts</code> \u200b\u4e0b\u200b\u7684\u200b\u5185\u5bb9\u200b\u4e0d\u53d8\u200b\uff0c\u200b\u5c06\u200b <code>puts</code> \u200b\u7684\u200b\u5185\u5bb9\u200b\u8f93\u51fa\u200b\u5230\u200b\u6587\u4ef6\u200b\u4e2d\u200b</p> <p>\u200b\u4f7f\u7528\u200b <code>open</code> \u200b\u5b9e\u73b0\u200b: \u200b\u7f3a\u70b9\u200b\u662f\u975e\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b\uff0c\u200b\u5982\u679c\u200b\u5728\u200b <code>close</code> \u200b\u548c\u200b <code>open</code> \u200b\u4e4b\u95f4\u200b\uff0c\u200b\u6709\u200b\u53e6\u200b\u4e00\u4e2a\u200b\u7ebf\u7a0b\u200b\u6253\u5f00\u200b\u4e86\u200b\u6587\u4ef6\u200b\u62a2\u5360\u200b\u4e86\u200b 1\uff0c\u200b\u91cd\u5b9a\u5411\u200b\u5c31\u200b\u4f1a\u200b\u5931\u8d25\u200b</p> <pre><code>#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;sys/types.h&gt;\n#include &lt;unistd.h&gt;\n\nint main(int argc, char* argv[])\n{\n    if (argc != 2)\n    {\n        fprintf(stderr, \"Usage: %s &lt;filename&gt;\\n\", argv[0]);\n        return EXIT_FAILURE;\n    }\n\n    close(STDOUT_FILENO); // \u200b\u9996\u5148\u200b\u5173\u95ed\u200b\u6807\u51c6\u200b\u8f93\u51fa\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n    // \u200b\u6253\u5f00\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\uff0c\u200b\u6b64\u65f6\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u8868\u4e2d\u200b\u6700\u5c0f\u200b\u7684\u200b\u53ef\u7528\u200b\u5c31\u662f\u200b 1\n    int fd = open(argv[1], O_CREAT | O_WRONLY | O_TRUNC, 0666);\n    if (fd &lt; 0)\n    {\n        perror(\"open() error\");\n        return EXIT_FAILURE;\n    }\n\n    // \u200b\u4fdd\u6301\u200b\u4e0b\u9762\u200b\u7684\u200b\u5185\u5bb9\u200b\u4e0d\u200b\u52a8\u200b\uff0c\u200b\u5c06\u200b\u4e0b\u9762\u200b\u7684\u200b\u5185\u5bb9\u200b\u8f93\u51fa\u200b\u7684\u200b\u5230\u200b\u6587\u4ef6\u200b\u4e2d\u200b\n    puts(\"Hello World!\");\n\n    close(fd);\n\n    return 0;\n}\n</code></pre> <p>\u200b\u4f7f\u7528\u200b <code>dup</code> \u200b\u5b9e\u73b0\u200b\uff1a\u200b\u7f3a\u70b9\u200b\u662f\u975e\u200b\u539f\u5b50\u200b\u64cd\u4f5c\u200b\uff0c<code>close</code> \u200b\u548c\u200b <code>dup</code> \u200b\u4e4b\u95f4\u200b\u5b58\u5728\u200b\u88ab\u200b\u62a2\u5360\u200b\u7684\u200b\u98ce\u9669\u200b</p> <pre><code>#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;sys/types.h&gt;\n#include &lt;unistd.h&gt;\n\nint main(int argc, char* argv[])\n{\n    if (argc != 2)\n    {\n        fprintf(stderr, \"Usage: %s &lt;filename&gt;\\n\", argv[0]);\n        return EXIT_FAILURE;\n    }\n\n    int fd = open(argv[1], O_WRONLY | O_CREAT | O_TRUNC, 0644);\n    if (fd &lt; 0)\n    {\n        perror(\"open error\");\n        return EXIT_FAILURE;\n    }\n\n    // \u200b\u5173\u95ed\u200b\u6807\u51c6\u200b\u8f93\u51fa\u200b\n    if (STDOUT_FILENO != fd)\n    {\n        close(STDOUT_FILENO);\n        dup(fd);  // \u200b\u590d\u5236\u200b fd\uff0c\u200b\u4ea7\u751f\u200b\u4e00\u4e2a\u200b\u5360\u7528\u200b 1 \u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n        close(fd);\n    }\n\n    // \u200b\u4fdd\u6301\u200b\u4e0b\u9762\u200b\u7684\u200b\u5185\u5bb9\u200b\u4e0d\u200b\u52a8\u200b\uff0c\u200b\u5c06\u200b\u4e0b\u9762\u200b\u7684\u200b\u5185\u5bb9\u200b\u8f93\u51fa\u200b\u7684\u200b\u5230\u200b\u6587\u4ef6\u200b\u4e2d\u200b\n    puts(\"Hello World!\");\n\n    return 0;\n}\n</code></pre> <p>\u200b\u4f7f\u7528\u200b <code>dup2</code> \u200b\u5b9e\u73b0\u200b\uff1a</p> <pre><code>#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;sys/stat.h&gt;\n#include &lt;sys/types.h&gt;\n#include &lt;unistd.h&gt;\n\nint main(int argc, char* argv[])\n{\n    if (argc != 2)\n    {\n        fprintf(stderr, \"Usage: %s &lt;filename&gt;\\n\", argv[0]);\n        return EXIT_FAILURE;\n    }\n\n    int fd = open(argv[1], O_WRONLY | O_CREAT | O_TRUNC, 0644);\n    if (fd &lt; 0)\n    {\n        perror(\"open error\");\n        return EXIT_FAILURE;\n    }\n\n    dup2(fd, STDOUT_FILENO);\n    close(fd);\n\n    puts(\"Hello World!\");\n\n    return 0;\n}\n</code></pre>"},{"location":"linux/linux-system-programming/file_io.html#\u6587\u4ef6\u63a7\u5236\u64cd\u4f5c-fcntl","title":"\u6587\u4ef6\u200b\u63a7\u5236\u200b\u64cd\u4f5c\u200b\uff1a <code>fcntl</code>","text":"<p><code>fcntl</code> \u200b\u88ab\u200b\u79f0\u4e3a\u200b Linux \u200b\u6587\u4ef6\u200b\u64cd\u4f5c\u200b\u7684\u200b\u201c\u200b\u745e\u58eb\u519b\u5200\u200b\u201d\u3002\u200b\u5b83\u200b\u53ef\u7528\u200b\u5bf9\u200b\u4e00\u4e2a\u200b\u5df2\u7ecf\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6267\u884c\u200b\u5404\u79cd\u5404\u6837\u200b\u7684\u200b\u63a7\u5236\u200b\u64cd\u4f5c\u200b\uff0c\u200b\u6bd4\u5982\u200b\u6539\u53d8\u200b\u6587\u4ef6\u200b\u7684\u200b\u5c5e\u6027\u200b\u3001\u200b\u8bbe\u7f6e\u200b\u975e\u200b\u963b\u585e\u200b\u3001\u200b\u83b7\u53d6\u200b\u6587\u4ef6\u200b\u9501\u200b\u7b49\u200b\u3002</p> <pre><code>#include &lt;unistd.h&gt;\n#include &lt;fcntl.h&gt;\n\n/**\n * @brief \u200b\u5bf9\u200b\u4e00\u4e2a\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6267\u884c\u200b\u4e00\u7cfb\u5217\u200b\u63a7\u5236\u200b\u64cd\u4f5c\u200b\n * @param fd    \u200b\u5df2\u200b\u6253\u5f00\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @param cmd   \u200b\u63a7\u5236\u200b\u64cd\u4f5c\u200b\u6307\u4ee4\u200b\n * @param ...   \u200b\u6839\u636e\u200b cmd \u200b\u7684\u200b\u4e0d\u540c\u200b\uff0c\u200b\u53ef\u80fd\u200b\u9700\u8981\u200b\u4f20\u9012\u200b\u7b2c\u4e09\u4e2a\u200b\u53ef\u200b\u9009\u200b\u53c2\u6570\u200b\uff08\u200b\u901a\u5e38\u200b\u662f\u200b int arg\uff09\n *  @return \u200b\u6210\u529f\u200b\u65f6\u200b\u7684\u200b\u8fd4\u56de\u503c\u200b\u89c6\u200b cmd \u200b\u800c\u5b9a\u200b\uff0c\u200b\u5931\u8d25\u200b\u7edf\u4e00\u200b\u8fd4\u56de\u200b -1 \u200b\u5e76\u200b\u8bbe\u7f6e\u200b errno\n * \n */\nint fcntl(int fd, int cmd, ... /* arg */ );\n</code></pre> <p><code>fcntl</code> \u200b\u51fd\u6570\u200b\u4e3b\u8981\u200b\u63d0\u4f9b\u200b\u4ee5\u4e0b\u200b 5 \u200b\u79cd\u200b\u529f\u80fd\u200b: </p> <ul> <li>\u200b\u590d\u5236\u200b\u4e00\u4e2a\u200b\u5df2\u6709\u200b\u7684\u200b\u63cf\u8ff0\u7b26\u200b\uff08cmd = <code>F_DUPFD</code> \u200b\u6216\u200b <code>F_DUPFD_CLOEXEC</code>\uff09</li> <li>\u200b\u83b7\u53d6\u200b/\u200b\u8bbe\u7f6e\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6807\u5fd7\u200b\uff08cmd = <code>F_GETFD</code> \u200b\u6216\u200b <code>F_SETFD</code>\uff09</li> <li>\u200b\u83b7\u53d6\u200b/\u200b\u8bbe\u7f6e\u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\uff08<code>cmd=F_GETFL</code> \u200b\u6216\u200b <code>F_SETFL</code>\uff09</li> <li>\u200b\u83b7\u53d6\u200b/\u200b\u8bbe\u7f6e\u200b\u5f02\u6b65\u200b I/O \u200b\u6240\u6709\u6743\u200b\uff08cmd = <code>F_GETOWN</code> \u200b\u6216\u200b <code>F_SETOWN</code>\uff09</li> <li>\u200b\u83b7\u53d6\u200b/\u200b\u8bbe\u7f6e\u200b\u8bb0\u5f55\u200b\u9501\u200b\uff08cmd = <code>F_GETLK\u3001F_SETLK</code> \u200b\u6216\u200b <code>F_SETLKW</code>\uff09</li> </ul> <p>\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6807\u5fd7\u200b vs \u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b</p> <ul> <li>\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6807\u5fd7\u200b\uff08FD\uff09\uff1a\u200b\u662f\u200b\u8fdb\u7a0b\u200b\u7ea7\u522b\u200b\u7684\u200b\uff0c\u200b\u6bd4\u5982\u200b <code>FD_CLOEXEC</code>\uff0c\u200b\u5b83\u200b\u53ea\u200b\u4f5c\u7528\u200b\u4e8e\u200b\u5f53\u524d\u200b\u8fdb\u7a0b\u200b\u7684\u200b\u8fd9\u4e2a\u200b <code>fd</code>\u3002</li> <li>\u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\uff08FL\uff09\uff1a\u200b\u662f\u200b\u7cfb\u7edf\u200b\u7ea7\u522b\u200b\u7684\u200b\uff08\u200b\u6253\u5f00\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\uff09\uff0c\u200b\u6bd4\u5982\u200b <code>O_RDWR</code>\u3001<code>O_APPEND</code>\u3001<code>O_NONBLOCK</code>\u3002\u200b\u5982\u679c\u200b\u901a\u8fc7\u200b <code>dup</code> \u200b\u590d\u5236\u200b\u4e86\u200b <code>fd</code>\uff0c\u200b\u6216\u8005\u200b <code>fork</code> \u200b\u4e86\u200b\u5b50\u200b\u8fdb\u7a0b\u200b\uff0c\u200b\u4fee\u6539\u200b\u8fd9\u4e2a\u200b\u6807\u5fd7\u200b\u4f1a\u200b\u5f71\u54cd\u200b\u6240\u6709\u200b\u6307\u5411\u200b\u8be5\u200b\u6587\u4ef6\u200b\u7684\u200b <code>fd</code>\u3002</li> </ul> <p>\u200b\u8be6\u7ec6\u200b\u63a7\u5236\u6307\u4ee4\u200b\u53c2\u8003\u200b\u4e0b\u8868\u200b\uff1a</p> \u200b\u76f8\u5173\u200b\u6807\u5fd7\u200b\uff08<code>cmd</code>\uff09 \u200b\u5177\u4f53\u200b\u63cf\u8ff0\u200b <code>F_DUPFD</code> \u200b\u590d\u5236\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b fd\uff0c\u200b\u65b0\u200b\u63cf\u8ff0\u7b26\u200b\u4f5c\u4e3a\u200b\u51fd\u6570\u200b\u8fd4\u56de\u503c\u200b\u3002\u200b\u5b83\u200b\u662f\u200b\u5c1a\u672a\u200b\u6253\u5f00\u200b\u7684\u200b\u63cf\u8ff0\u7b26\u200b\u4e2d\u200b\uff0c\u200b\u5927\u4e8e\u200b\u6216\u200b\u7b49\u4e8e\u200b\u7b2c\u4e09\u4e2a\u200b\u53c2\u6570\u200b <code>arg</code> \u200b\u7684\u200b\u6700\u5c0f\u503c\u200b\u3002\u200b\u65b0\u200b\u63cf\u8ff0\u7b26\u200b\u4e0e\u200b\u539f\u200b <code>fd</code> \u200b\u5171\u4eab\u200b\u540c\u4e00\u4e2a\u200b\u201c\u200b\u6587\u4ef6\u200b\u8868\u9879\u200b\u201d\uff0c\u200b\u4f46\u200b\u62e5\u6709\u200b\u81ea\u5df1\u200b\u7684\u200b\u201c\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6807\u5fd7\u200b\u201d\uff08\u200b\u5176\u200b <code>FD_CLOEXEC</code> \u200b\u4f1a\u200b\u88ab\u200b\u6e05\u9664\u200b\uff09 <code>F_DUPFD_CLOEXEC</code> \u200b\u4f3c\u4e8e\u200b <code>F_DUPFD</code>\uff0c\u200b\u4f46\u200b\u5728\u200b\u590d\u5236\u200b\u7684\u200b\u540c\u65f6\u200b\uff0c\u200b\u539f\u5b50\u200b\u6027\u200b\u5730\u200b\u8bbe\u7f6e\u200b\u65b0\u200b\u63cf\u8ff0\u7b26\u200b\u7684\u200b <code>FD_CLOEXEC</code> \u200b\u6807\u5fd7\u200b <code>F_GETFD</code> \u200b\u8fd4\u56de\u200b\u5bf9\u5e94\u200b <code>fd</code> \u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6807\u5fd7\u200b\uff0c\u200b\u76ee\u524d\u200b\u53ea\u200b\u5b9a\u4e49\u200b\u4e86\u200b\u4e00\u4e2a\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6807\u5fd7\u200b <code>FD_CLOEXEC</code> <code>F_SETFD</code> \u200b\u8bbe\u7f6e\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u6807\u5fd7\u200b\uff0c\u200b\u65b0\u200b\u6807\u5fd7\u200b\u503c\u200b\u7531\u200b\u7b2c\u4e09\u4e2a\u200b\u53c2\u6570\u200b <code>arg</code> \u200b\u51b3\u5b9a\u200b <code>F_GETFL</code> \u200b\u8fd4\u56de\u200b\u5bf9\u5e94\u200b <code>fd</code> \u200b\u7684\u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\uff08\u200b\u5982\u200b\u53ea\u8bfb\u200b\u3001\u200b\u53ef\u200b\u5199\u200b\u3001\u200b\u8ffd\u52a0\u200b\u7b49\u200b\uff09 <code>F_SETFL</code> \u200b\u8bbe\u7f6e\u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\uff0c\u200b\u65b0\u200b\u6807\u5fd7\u200b\u503c\u200b\u7531\u200b\u7b2c\u4e09\u4e2a\u200b\u53c2\u6570\u200b <code>arg</code> \u200b\u51b3\u5b9a\u200b\u3002\u200b\u6ce8\u200b\uff1a\u200b\u4ec5\u80fd\u200b\u66f4\u6539\u200b <code>O_APPEND</code>\u3001<code>O_NONBLOCK</code>\u3001<code>O_SYNC</code>\u3001<code>O_ASYNC</code> \u200b\u7b49\u200b\u6807\u5fd7\u200b\uff0c\u200b\u65e0\u6cd5\u200b\u66f4\u6539\u200b\u6587\u4ef6\u200b\u7684\u200b\u8bfb\u5199\u200b\u6743\u9650\u200b\uff08\u200b\u5982\u200b <code>O_RDONLY</code> \u200b\u7b49\u200b\u5728\u200b <code>open</code> \u200b\u65f6\u200b\u5c31\u200b\u5df2\u5b9a\u200b\u6b7b\u200b\uff09 <code>F_GETOWN</code> \u200b\u83b7\u53d6\u200b\u5f53\u524d\u200b\u63a5\u6536\u200b <code>SIGIO</code> \u200b\u548c\u200b <code>SIGURG</code> \u200b\u4fe1\u53f7\u200b\u7684\u200b\u8fdb\u7a0b\u200b ID \u200b\u6216\u200b\u8fdb\u7a0b\u200b\u7ec4\u200b ID <code>F_SETOWN</code> \u200b\u8bbe\u7f6e\u200b\u63a5\u6536\u200b <code>SIGIO</code> \u200b\u548c\u200b <code>SIGURG</code> \u200b\u4fe1\u53f7\u200b\u7684\u200b\u8fdb\u7a0b\u200b ID \u200b\u6216\u200b\u8fdb\u7a0b\u200b\u7ec4\u200b ID\u3002\u200b\u6b63\u200b\u7684\u200b <code>arg</code> \u200b\u6307\u5b9a\u200b\u4e00\u4e2a\u200b\u8fdb\u7a0b\u200b ID\uff0c\u200b\u8d1f\u200b\u7684\u200b <code>arg</code> \u200b\u8868\u793a\u200b\u7b49\u4e8e\u200b <code>arg</code> \u200b\u7edd\u5bf9\u503c\u200b\u7684\u200b\u4e00\u4e2a\u200b\u8fdb\u7a0b\u200b\u7ec4\u200b ID <p><code>fcntl</code> \u200b\u6700\u200b\u7ecf\u5178\u200b\u7684\u200b\u5e94\u7528\u200b\u573a\u666f\u200b\u662f\u200b\u5728\u200b \u200b\u7f51\u7edc\u200b\u7f16\u7a0b\u200b / \u200b\u9ad8\u200b\u5e76\u53d1\u200b\u670d\u52a1\u5668\u200b\uff08\u200b\u5982\u200b <code>epoll</code>\uff09 \u200b\u4e2d\u200b\uff0c\u200b\u5c06\u200b\u4e00\u4e2a\u200b Socket \u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u8bbe\u7f6e\u200b\u4e3a\u200b\u975e\u200b\u963b\u585e\u200b\u6a21\u5f0f\u200b\u3002\u200b\u8fd9\u200b\u610f\u5473\u7740\u200b\u5f53\u200b\u7f51\u7edc\u200b\u4e2d\u200b\u6ca1\u6709\u200b\u6570\u636e\u200b\u65f6\u200b\uff0c<code>read</code> \u200b\u64cd\u4f5c\u200b\u4e0d\u4f1a\u200b\u8ba9\u200b\u8fdb\u7a0b\u200b\u7761\u7720\u200b\u5361\u6b7b\u200b\uff0c\u200b\u800c\u662f\u200b\u7acb\u523b\u200b\u8fd4\u56de\u200b -1 \u200b\u5e76\u200b\u629b\u51fa\u200b <code>EAGAIN</code> \u200b\u9519\u8bef\u200b\u3002</p> <p>\u200b\u5728\u200b\u66f4\u6539\u200b\u6587\u4ef6\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\u65f6\u200b\uff0c\u200b\u6211\u4eec\u200b\u5fc5\u987b\u200b\u4e25\u683c\u200b\u9075\u5faa\u200b \u201c\u200b\u8bfb\u200b -&gt; \u200b\u6539\u200b -&gt; \u200b\u5199\u200b (Read-Modify-Write)\u201d \u200b\u7684\u200b\u6a21\u5f0f\u200b\u3002</p> <pre><code>#include &lt;fcntl.h&gt;\n#include &lt;stdio.h&gt;\n\n/**\n * @brief \u200b\u5c06\u200b\u6307\u5b9a\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u8bbe\u7f6e\u200b\u4e3a\u200b\u975e\u200b\u963b\u585e\u200b\u6a21\u5f0f\u200b\n * @param fd \u200b\u9700\u8981\u200b\u64cd\u4f5c\u200b\u7684\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\n * @return \u200b\u6210\u529f\u200b\u8fd4\u56de\u200b\u65e7\u200b\u7684\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\uff08\u200b\u4ee5\u4fbf\u200b\u65e5\u540e\u200b\u6062\u590d\u200b\uff09\uff0c\u200b\u5931\u8d25\u200b\u8fd4\u56de\u200b -1\n * \n */\nint set_nonblocking(int fd) {\n    // \u200b\u83b7\u53d6\u200b\u6587\u4ef6\u200b\u63cf\u8ff0\u7b26\u200b\u5f53\u524d\u200b\u7684\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b (Flags)\n    int old_flags = fcntl(fd, F_GETFL);  \n    if (old_flags == -1) {\n        perror(\"fcntl F_GETFL error\");\n        return -1;\n    }\n\n    // \u200b\u5728\u200b\u539f\u200b\u6807\u5fd7\u200b\u7684\u200b\u57fa\u7840\u200b\u4e0a\u200b\uff0c\u200b\u6309\u200b\u4f4d\u6216\u200b (|) \u200b\u52a0\u4e0a\u200b\u975e\u200b\u963b\u585e\u200b\u6807\u5fd7\u200b\n    int new_flags = old_flags | O_NONBLOCK; \n\n    // \u200b\u5199\u200b\u5c06\u200b\u65b0\u200b\u7684\u200b\u72b6\u6001\u200b\u6807\u5fd7\u200b\u8bbe\u7f6e\u200b\u56de\u53bb\u200b\n    if (fcntl(fd, F_SETFL, new_flags) == -1) {\n        perror(\"fcntl F_SETFL error\");\n        return -1;\n    }\n\n    // \u200b\u8fd4\u56de\u200b\u65e7\u200b\u7684\u200b\u6807\u5fd7\u200b\uff0c\u200b\u65b9\u4fbf\u200b\u8c03\u7528\u8005\u200b\u5728\u200b\u9700\u8981\u200b\u65f6\u200b\u6062\u590d\u539f\u72b6\u200b\n    return old_flags;  \n}\n</code></pre> <p>\u200b\u4e3a\u4ec0\u4e48\u200b\u4e0d\u80fd\u200b\u76f4\u63a5\u200b <code>fcntl(fd, F_SETFL, O_NONBLOCK)</code>\uff1f</p> <p>\u200b\u56e0\u4e3a\u200b <code>F_SETFL</code> \u200b\u64cd\u4f5c\u200b\u662f\u200b\u5b8c\u5168\u200b\u8986\u76d6\u200b\uff0c\u200b\u5982\u679c\u200b\u8fd9\u4e2a\u200b\u6587\u4ef6\u200b\u6700\u521d\u200b\u662f\u200b\u4ee5\u200b\u8ffd\u52a0\u200b\u6a21\u5f0f\u200b\uff08<code>O_APPEND</code>\uff09\u200b\u6253\u5f00\u200b\u7684\u200b\uff0c\u200b\u6211\u4eec\u200b\u76f4\u63a5\u200b\u6267\u884c\u200b <code>fcntl(fd, F_SETFL, O_NONBLOCK)</code>\uff0c\u200b\u975e\u200b\u963b\u585e\u200b\u7279\u6027\u200b\u786e\u5b9e\u200b\u52a0\u4e0a\u200b\u4e86\u200b\uff0c\u200b\u4f46\u200b\u539f\u6765\u200b\u7684\u200b <code>O_APPEND</code> \u200b\u5c5e\u6027\u200b\u5c31\u200b\u4f1a\u200b\u88ab\u200b\u65e0\u60c5\u5730\u200b\u60c5\u51b5\u200b\u62b9\u9664\u200b\u3002\u200b\u56e0\u6b64\u200b\uff0c\u200b\u6b63\u786e\u200b\u7684\u200b\u505a\u6cd5\u200b\u6c38\u8fdc\u200b\u662f\u200b\u5148\u200b <code>GET</code> \u200b\u62ff\u5230\u200b\u5f53\u524d\u200b\u5c5e\u6027\u200b\uff0c\u200b\u4f7f\u7528\u200b\u6309\u200b\u4f4d\u6216\u200b <code>|</code> \u200b\u52a0\u4e0a\u200b\u65b0\u200b\u5c5e\u6027\u200b\uff0c\u200b\u7136\u540e\u200b\u518d\u200b <code>SET</code> \u200b\u56de\u53bb\u200b\u3002</p>"}]}